export default [{"id":"294","jozz":"3","page":"50","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"3","line_end":"3","aya_no":"1","aya_text":"الٓمٓ","aya_text_emlaey":"الم","aya_tafseer":"[1] الٓمٓ سبق الكلام عليها في أول سورة البقرة."},{"id":"295","jozz":"3","page":"50","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"3","line_end":"3","aya_no":"2","aya_text":"ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُ","aya_text_emlaey":"الله لا إله إلا هو الحي القيوم","aya_tafseer":"[2] هو الله، لا معبود بحق إلا هو، المتصف بالحياة الكاملة كما يليق بجلاله، القائم على كل شيء."},{"id":"296","jozz":"3","page":"50","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"3","line_end":"4","aya_no":"3","aya_text":"نَزَّلَ عَلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ وَأَنزَلَ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ","aya_text_emlaey":"نـزل عليك الكتاب بالحق مصدقا لما بين يديه وأنـزل التوراة والإنجيل","aya_tafseer":"[3] نَزَّل عليك -أيها الرسول- القرآنَ بالحق الذي لا ريب فيه، يشهد على صدق ما قبله من كتب ورسل، وأنزل التوراة على موسى عليه السلام، والإنجيل على عيسى عليه السلام"},{"id":"297","jozz":"3","page":"50","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"4","line_end":"6","aya_no":"4","aya_text":"مِن قَبۡلُ هُدٗى لِّلنَّاسِ وَأَنزَلَ ٱلۡفُرۡقَانَۗ إِنَّ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ لَهُمۡ عَذَابٞ شَدِيدٞۗ وَٱللَّهُ عَزِيزٞ ذُو ٱنتِقَامٍ","aya_text_emlaey":"من قبل هدى للناس وأنـزل الفرقان إن الذين كفروا بآيات الله لهم عذاب شديد والله عزيز ذو انتقام","aya_tafseer":"[4] من قبل نزول القرآن؛ لإرشاد المتقين إلى الإيمان، وصلاح دينهم ودنياهم، وأنزل ما يفرق بين الحق والباطل. والذين كفروا بآيات الله المنزلة، لهم عذاب عظيم. والله عزيز لا يُغالَبُ، ذو انتقام ممن جحد حججه وأدلته، وتفرُّده بالألوهية."},{"id":"298","jozz":"3","page":"50","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"6","line_end":"7","aya_no":"5","aya_text":"إِنَّ ٱللَّهَ لَا يَخۡفَىٰ عَلَيۡهِ شَيۡءٞ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ","aya_text_emlaey":"إن الله لا يخفى عليه شيء في الأرض ولا في السماء","aya_tafseer":"[5] إن الله محيط علمه بالخلائق، لا يخفى عليه شيء في الأرض ولا في السماء، قلَّ أو كثر."},{"id":"299","jozz":"3","page":"50","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"7","line_end":"8","aya_no":"6","aya_text":"هُوَ ٱلَّذِي يُصَوِّرُكُمۡ فِي ٱلۡأَرۡحَامِ كَيۡفَ يَشَآءُۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ","aya_text_emlaey":"هو الذي يصوركم في الأرحام كيف يشاء لا إله إلا هو العزيز الحكيم","aya_tafseer":"[6] هو وحده الذي يخلقكم في أرحام أمهاتكم كما يشاء، مِن ذكر وأنثى، وحسن وقبيح، وشقي وسعيد، لا معبود بحق سواه، العزيز الذي لا يُغالَب، الحكيم في أمره وتدبيره."},{"id":"300","jozz":"3","page":"50","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"13","aya_no":"7","aya_text":"هُوَ ٱلَّذِيٓ أَنزَلَ عَلَيۡكَ ٱلۡكِتَٰبَ مِنۡهُ ءَايَٰتٞ مُّحۡكَمَٰتٌ هُنَّ أُمُّ ٱلۡكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتٞۖ فَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِمۡ زَيۡغٞ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنۡهُ ٱبۡتِغَآءَ ٱلۡفِتۡنَةِ وَٱبۡتِغَآءَ تَأۡوِيلِهِۦۖ وَمَا يَعۡلَمُ تَأۡوِيلَهُۥٓ إِلَّا ٱللَّهُۗ وَٱلرَّٰسِخُونَ فِي ٱلۡعِلۡمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلّٞ مِّنۡ عِندِ رَبِّنَاۗ وَمَا يَذَّكَّرُ إِلَّآ أُوْلُواْ ٱلۡأَلۡبَٰبِ","aya_text_emlaey":"هو الذي أنـزل عليك الكتاب منه آيات محكمات هن أم الكتاب وأخر متشابهات فأما الذين في قلوبهم زيغ فيتبعون ما تشابه منه ابتغاء الفتنة وابتغاء تأويله وما يعلم تأويله إلا الله والراسخون في العلم يقولون آمنا به كل من عند ربنا وما يذكر إلا أولو الألباب","aya_tafseer":"[7] هو وحده الذي أنزل عليك القرآن: منه آيات واضحات الدلالة، هن أصل الكتاب الذي يُرجع إليه عند الاشتباه، ويُرَدُّ ما خالفه إليه، ومنه آيات أُخر متشابهات تحتمل بعض المعاني، لا يتعيَّن المراد منها إلا بضمها إلى المحكم، فأصحاب القلوب المريضة الزائغة، لسوء قصدهم يتبعون هذه الآيات المتشابهات وحدها؛ ليثيروا الشبهات عند الناس، كي يضلوهم، ولتأويلهم لها على مذاهبهم الباطلة. ولا يعلم حقيقة هذه الآيات المتشابهات وما تؤول إليه إلا الله. والمتمكنون في العلم يقولون: آمنا بهذا القرآن، كلُّه قد جاءنا من عند ربنا على لسان رسوله محمد -صلى الله عليه وسلم-، ويردُّون متشابهه إلى محكمه، وإنما يفهم ويعقل ويتدبَّر المعاني على وجهها الصحيح أولو العقول السليمة."},{"id":"301","jozz":"3","page":"50","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"13","line_end":"14","aya_no":"8","aya_text":"رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَيۡتَنَا وَهَبۡ لَنَا مِن لَّدُنكَ رَحۡمَةًۚ إِنَّكَ أَنتَ ٱلۡوَهَّابُ","aya_text_emlaey":"ربنا لا تزغ قلوبنا بعد إذ هديتنا وهب لنا من لدنك رحمة إنك أنت الوهاب","aya_tafseer":"[8] ويقولون: يا ربنا لا تصْرِف قلوبنا عن الإيمان بك بعد أن مننت علينا بالهداية لدينك، وامنحنا من فضلك رحمة واسعة، إنك أنت الوهاب: كثير الفضل والعطاء، تعطي مَن تشاء بغير حساب."},{"id":"302","jozz":"3","page":"50","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"14","line_end":"15","aya_no":"9","aya_text":"رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوۡمٖ لَّا رَيۡبَ فِيهِۚ إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ","aya_text_emlaey":"ربنا إنك جامع الناس ليوم لا ريب فيه إن الله لا يخلف الميعاد","aya_tafseer":"[9] يا ربنا إننا نُقِرُّ ونشهد بأنك ستجمع الناس في يوم لاشَكَّ فيه، وهو يوم القيامة، إنَّك لا تُخلف ما وَعَدْتَ به عبادك."},{"id":"303","jozz":"3","page":"51","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"2","aya_no":"10","aya_text":"إِنَّ ٱلَّذِينَ كَفَرُواْ لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـٔٗاۖ وَأُوْلَٰٓئِكَ هُمۡ وَقُودُ ٱلنَّارِ","aya_text_emlaey":"إن الذين كفروا لن تغني عنهم أموالهم ولا أولادهم من الله شيئا وأولئك هم وقود النار","aya_tafseer":"[10] إن الذين جحدوا الدِّينَ الحقَّ وأنكروه، لن تنفعهم أموالهم ولا أولادهم من عذاب الله شيئاً إن وقع بهم في الدنيا، ولن تدفعه عنهم في الآخرة، وهؤلاء هم حطب النار يوم القيامة."},{"id":"304","jozz":"3","page":"51","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"2","line_end":"4","aya_no":"11","aya_text":"كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَّبُواْ بِـَٔايَٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡۗ وَٱللَّهُ شَدِيدُ ٱلۡعِقَابِ","aya_text_emlaey":"كدأب آل فرعون والذين من قبلهم كذبوا بآياتنا فأخذهم الله بذنوبهم والله شديد العقاب","aya_tafseer":"[11] شأن الكافرين في تكذيبهم وما ينزل بهم، شأن آل فرعون والذين من قبلهم من الكافرين، أنكروا آيات الله الواضحة، فعاجلهم بالعقوبة بسبب تكذيبهم وعنادهم. والله شديد العقاب لمن كفر به وكذَّب رسله."},{"id":"305","jozz":"3","page":"51","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"4","line_end":"5","aya_no":"12","aya_text":"قُل لِّلَّذِينَ كَفَرُواْ سَتُغۡلَبُونَ وَتُحۡشَرُونَ إِلَىٰ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمِهَادُ","aya_text_emlaey":"قل للذين كفروا ستغلبون وتحشرون إلى جهنم وبئس المهاد","aya_tafseer":"[12] قل -أيها الرسول- للذين كفروا من اليهود وغيرهم والذين استهانوا بنصرك في «بَدْر»: إنكم ستُهْزَمون في الدنيا وستموتون على الكفر، وتُجْمعون إلى نار جهنم؛ لتكون فراشاً دائماً لكم، وبئس الفراش."},{"id":"306","jozz":"3","page":"51","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"6","line_end":"9","aya_no":"13","aya_text":"قَدۡ كَانَ لَكُمۡ ءَايَةٞ فِي فِئَتَيۡنِ ٱلۡتَقَتَاۖ فِئَةٞ تُقَٰتِلُ فِي سَبِيلِ ٱللَّهِ وَأُخۡرَىٰ كَافِرَةٞ يَرَوۡنَهُم مِّثۡلَيۡهِمۡ رَأۡيَ ٱلۡعَيۡنِۚ وَٱللَّهُ يُؤَيِّدُ بِنَصۡرِهِۦ مَن يَشَآءُۚ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّأُوْلِي ٱلۡأَبۡصَٰرِ","aya_text_emlaey":"قد كان لكم آية في فئتين التقتا فئة تقاتل في سبيل الله وأخرى كافرة يرونهم مثليهم رأي العين والله يؤيد بنصره من يشاء إن في ذلك لعبرة لأولي الأبصار","aya_tafseer":"[13] قد كان لكم -أيها اليهود المتكبرون المعاندون- دلالة عظيمة في جماعتين تقابلتا في معركة «بَدْر»: جماعة تقاتل من أجل دين الله، وهم محمد -صلى الله عليه وسلم- وأصحابه، وجماعة أخرى كافرة بالله، تقاتل من أجل الباطل، ترى المؤمنين في العدد مثليهم رأي العين، وقد جعل الله ذلك سبباً لنصر المسلمين عليهم. والله يؤيِّد بنصره من يشاء من عباده. إن في هذا الذي حدث لَعظة عظيمة لأصحاب البصائر الذين يهتدون إلى حكم الله وأفعاله."},{"id":"307","jozz":"3","page":"51","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"9","line_end":"12","aya_no":"14","aya_text":"زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلۡبَنِينَ وَٱلۡقَنَٰطِيرِ ٱلۡمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلۡفِضَّةِ وَٱلۡخَيۡلِ ٱلۡمُسَوَّمَةِ وَٱلۡأَنۡعَٰمِ وَٱلۡحَرۡثِۗ ذَٰلِكَ مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلۡمَـَٔابِ","aya_text_emlaey":"زين للناس حب الشهوات من النساء والبنين والقناطير المقنطرة من الذهب والفضة والخيل المسومة والأنعام والحرث ذلك متاع الحياة الدنيا والله عنده حسن المآب","aya_tafseer":"[14] حُسِّن للناس حبُّ الشهوات من النساء والبنين، والأموال الكثيرة من الذهب والفضة، والخيل الحسان، والأنعام من الإبل والبقر والغنم، والأرض المتَّخَذة للغراس والزراعة. ذلك زهرة الحياة الدنيا وزينتها الفانية. والله عنده حسن المرجع والثواب، وهو الجنَّة."},{"id":"308","jozz":"3","page":"51","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"15","aya_no":"15","aya_text":"۞ قُلۡ أَؤُنَبِّئُكُم بِخَيۡرٖ مِّن ذَٰلِكُمۡۖ لِلَّذِينَ ٱتَّقَوۡاْ عِندَ رَبِّهِمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَأَزۡوَٰجٞ مُّطَهَّرَةٞ وَرِضۡوَٰنٞ مِّنَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ","aya_text_emlaey":"قل أؤنبئكم بخير من ذلكم للذين اتقوا عند ربهم جنات تجري من تحتها الأنهار خالدين فيها وأزواج مطهرة ورضوان من الله والله بصير بالعباد","aya_tafseer":"[15] قل -أيها الرسول-: أأخبركم بخير مما زُيِّن للنَّاس في هذه الحياة الدنيا، لمن راقب الله وخاف عقابه جنات تجري من تحت قصورها وأشجارها الأنهار، خالدين فيها، ولهم فيها أزواج مطهَّرات من الحيض والنِّفاس، وسوء الخلق، ولهم أعظم من ذلك: رضوان من الله. والله مُطَّلِع على سرائر خلقه، عالم بأحوالهم، وسيجازيهم على ذلك."},{"id":"309","jozz":"3","page":"52","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"2","aya_no":"16","aya_text":"ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ","aya_text_emlaey":"الذين يقولون ربنا إننا آمنا فاغفر لنا ذنوبنا وقنا عذاب النار","aya_tafseer":"[16] هؤلاء العباد المتقون يقولون: إننا آمنا بك، واتبعنا رسولك محمداً -صلى الله عليه وسلم-، فامْحُ عنا ما اقترفناه من ذنوب، ونجنا من عذاب النار."},{"id":"310","jozz":"3","page":"52","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"2","line_end":"3","aya_no":"17","aya_text":"ٱلصَّٰبِرِينَ وَٱلصَّٰدِقِينَ وَٱلۡقَٰنِتِينَ وَٱلۡمُنفِقِينَ وَٱلۡمُسۡتَغۡفِرِينَ بِٱلۡأَسۡحَارِ","aya_text_emlaey":"الصابرين والصادقين والقانتين والمنفقين والمستغفرين بالأسحار","aya_tafseer":"[17] هم الذين اتصفوا بالصبر على الطاعات، وعن المعاصي، وعلى ما يصيبهم من أقدار الله المؤلمة، وبالصدق في الأقوال والأفعال، وبالطاعة التامة، وبالإنفاق سرّاً وعلانية، وبالاستغفار في آخر الليل؛ لأنه مَظِنَّة القَبول وإجابة الدعاء."},{"id":"311","jozz":"3","page":"52","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"3","line_end":"5","aya_no":"18","aya_text":"شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلۡمَلَٰٓئِكَةُ وَأُوْلُواْ ٱلۡعِلۡمِ قَآئِمَۢا بِٱلۡقِسۡطِۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ","aya_text_emlaey":"شهد الله أنه لا إله إلا هو والملائكة وأولو العلم قائما بالقسط لا إله إلا هو العزيز الحكيم","aya_tafseer":"[18] شهد الله أنه المتفرد بالإلهية، وقَرَنَ شهادته بشهادة الملائكة وأهل العلم، على أجلِّ مشهود عليه، وهو توحيده تعالى وقيامه بالعدل، لا إله إلا هو العزيز الذي لا يمتنع عليه شيء أراده، الحكيم في أقواله وأفعاله."},{"id":"312","jozz":"3","page":"52","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"5","line_end":"8","aya_no":"19","aya_text":"إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ وَمَا ٱخۡتَلَفَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۗ وَمَن يَكۡفُرۡ بِـَٔايَٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ","aya_text_emlaey":"إن الدين عند الله الإسلام وما اختلف الذين أوتوا الكتاب إلا من بعد ما جاءهم العلم بغيا بينهم ومن يكفر بآيات الله فإن الله سريع الحساب","aya_tafseer":"[19] إن الدين الذي ارتضاه الله لخلقه وأرسل به رسله، ولا يَقْبل غيره هو الإسلام، وهو الانقياد لله وحده بالطاعة والاستسلام له بالعبودية، واتباع الرسل فيما بعثهم الله به في كل حين حتى خُتموا بمحمد -صلى الله عليه وسلم-، الذي لا يقبل الله مِن أحد بعد بعثته ديناً سوى الإسلام الذي أُرسل به. وما وقع الخلاف بين أهل الكتاب من اليهود والنصارى، فتفرقوا شيعاً وأحزاباً إلَّا من بعد ما قامت الحجة عليهم بإرسال الرسل وإنزال الكتب؛ بغياً وحسداً طلباً للدنيا. ومن يجحد آيات الله المنزلة وآياته الدالة على ربوبيته وأُلوهيته، فإن الله سريع الحساب، وسيجزيهم بما كانوا يعملون."},{"id":"313","jozz":"3","page":"52","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"11","aya_no":"20","aya_text":"فَإِنۡ حَآجُّوكَ فَقُلۡ أَسۡلَمۡتُ وَجۡهِيَ لِلَّهِ وَمَنِ ٱتَّبَعَنِۗ وَقُل لِّلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَٱلۡأُمِّيِّـۧنَ ءَأَسۡلَمۡتُمۡۚ فَإِنۡ أَسۡلَمُواْ فَقَدِ ٱهۡتَدَواْۖ وَّإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ","aya_text_emlaey":"فإن حاجوك فقل أسلمت وجهي لله ومن اتبعن وقل للذين أوتوا الكتاب والأميين أأسلمتم فإن أسلموا فقد اهتدوا وإن تولوا فإنما عليك البلاغ والله بصير بالعباد","aya_tafseer":"[20] فإن جادلك -أيها الرسول- أهل الكتاب في التوحيد بعد أن أقمت الحجة عليهم فقل لهم: إنني أخلصت لله وحده فلا أشرك به أحداً، وكذلك من اتبعني من المؤمنين، أخلصوا لله وانقادوا له. وقل لهم ولمشركي العرب وغيرهم: إن أسلمتم فأنتم على الطريق المستقيم والهدى والحق، وإن توليتم فحسابكم على الله، وليس عليَّ إلَّا البلاغ، وقد أبلغتكم وأقمت عليكم الحجة. والله بصير بالعباد، لا يخفى عليه من أمرهم شيء."},{"id":"314","jozz":"3","page":"52","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"14","aya_no":"21","aya_text":"إِنَّ ٱلَّذِينَ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيۡرِ حَقّٖ وَيَقۡتُلُونَ ٱلَّذِينَ يَأۡمُرُونَ بِٱلۡقِسۡطِ مِنَ ٱلنَّاسِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ","aya_text_emlaey":"إن الذين يكفرون بآيات الله ويقتلون النبيين بغير حق ويقتلون الذين يأمرون بالقسط من الناس فبشرهم بعذاب أليم","aya_tafseer":"[21] إن الذين يجحدون بالدلائل الواضحة وما جاء به المرسلون، ويقتلون أنبياء الله ظلماً بغير حق، ويقتلون الذين يأمرون بالعدل واتباع طريق الأنبياء، فبشِّرهم بعذاب موجع."},{"id":"315","jozz":"3","page":"52","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"14","line_end":"15","aya_no":"22","aya_text":"أُوْلَٰٓئِكَ ٱلَّذِينَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ","aya_text_emlaey":"أولئك الذين حبطت أعمالهم في الدنيا والآخرة وما لهم من ناصرين","aya_tafseer":"[22] أولئك الذين بطلت أعمالهم في الدنيا والآخرة، فلا يُقبل لهم عمل، وما لهم مِن ناصرٍ ينصرهم من عذاب الله."},{"id":"316","jozz":"3","page":"53","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"2","aya_no":"23","aya_text":"أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يُدۡعَوۡنَ إِلَىٰ كِتَٰبِ ٱللَّهِ لِيَحۡكُمَ بَيۡنَهُمۡ ثُمَّ يَتَوَلَّىٰ فَرِيقٞ مِّنۡهُمۡ وَهُم مُّعۡرِضُونَ","aya_text_emlaey":"ألم تر إلى الذين أوتوا نصيبا من الكتاب يدعون إلى كتاب الله ليحكم بينهم ثم يتولى فريق منهم وهم معرضون","aya_tafseer":"[23] أرأيت -أيها الرسول- أعجب من حال هؤلاء اليهود الذين آتاهم الله حظّاً من الكتاب فعلموا أن ما جئت به هو الحق، يُدْعون إلى ما جاء في كتاب الله -وهو القرآن- ليفصل بينهم فيما اختلفوا فيه، فإن لم يوافق أهواءهم يَأْبَ كثير منهم حكم الله؛ لأنَّ من عادتهم الإعراضَ عن الحق؟"},{"id":"317","jozz":"3","page":"53","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"3","line_end":"4","aya_no":"24","aya_text":"ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَٰتٖۖ وَغَرَّهُمۡ فِي دِينِهِم مَّا كَانُواْ يَفۡتَرُونَ","aya_text_emlaey":"ذلك بأنهم قالوا لن تمسنا النار إلا أياما معدودات وغرهم في دينهم ما كانوا يفترون","aya_tafseer":"[24] ذلك الانصراف عن الحق سببه اعتقاد فاسد لدى أهل الكتاب؛ بأنهم لن يعذَّبوا إلَّا أياماً قليلة، وهذا الاعتقاد أدى إلى جرأتهم على الله واستهانتهم بدينه، واستمرارهم على دينهم الباطل الذي خَدَعوا به أنفسهم."},{"id":"318","jozz":"3","page":"53","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"4","line_end":"6","aya_no":"25","aya_text":"فَكَيۡفَ إِذَا جَمَعۡنَٰهُمۡ لِيَوۡمٖ لَّا رَيۡبَ فِيهِ وَوُفِّيَتۡ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ","aya_text_emlaey":"فكيف إذا جمعناهم ليوم لا ريب فيه ووفيت كل نفس ما كسبت وهم لا يظلمون","aya_tafseer":"[25] فكيف يكون حالهم إذا جمعهم الله ليحاسَبوا في يوم لا شك في وقوعه -وهو يوم القيامة-، وأخذ كل واحد جزاءَ ما اكتسب، وهم لا يظلمون شيئاً؟"},{"id":"319","jozz":"3","page":"53","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"6","line_end":"8","aya_no":"26","aya_text":"قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلۡمُلۡكِ تُؤۡتِي ٱلۡمُلۡكَ مَن تَشَآءُ وَتَنزِعُ ٱلۡمُلۡكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُۖ بِيَدِكَ ٱلۡخَيۡرُۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","aya_text_emlaey":"قل اللهم مالك الملك تؤتي الملك من تشاء وتنـزع الملك ممن تشاء وتعز من تشاء وتذل من تشاء بيدك الخير إنك على كل شيء قدير","aya_tafseer":"[26] قل -أيها النبي متوجهاً إلى ربك بالدعاء-: يا مَن لك الملك كلُّه، أنت الذي تمنح الملك والمال والتمكين في الأرض مَن تشاء مِن خلقك، وتَسْلُب الملك ممن تشاء، وتهب العزة في الدنيا والآخرة من تشاء، وتجعل الذلَّة على مَن تشاء، بيدك الخير، إنك -وحدك- على كل شيء قدير. وفي الآية إثبات لصفة اليد لله تعالى على ما يليق به سبحانه."},{"id":"320","jozz":"3","page":"53","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"10","aya_no":"27","aya_text":"تُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِۖ وَتُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَتُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّۖ وَتَرۡزُقُ مَن تَشَآءُ بِغَيۡرِ حِسَابٖ","aya_text_emlaey":"تولج الليل في النهار وتولج النهار في الليل وتخرج الحي من الميت وتخرج الميت من الحي وترزق من تشاء بغير حساب","aya_tafseer":"[27] ومن دلائل قدرتك أنك تُدخل الليل في النهار، وتدخل النهار في الليل، فيطول هذا ويقصر ذاك، وتُخرج الحي من الميت الذي لا حياة فيه، كإخراج الزرع من الحب، والمؤمن من الكافر، وتُخرج الميت من الحي كإخراج البيض من الدجاج، وترزق مَن تشاء مِن خلقك بغير حساب."},{"id":"321","jozz":"3","page":"53","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"11","line_end":"13","aya_no":"28","aya_text":"لَّا يَتَّخِذِ ٱلۡمُؤۡمِنُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۖ وَمَن يَفۡعَلۡ ذَٰلِكَ فَلَيۡسَ مِنَ ٱللَّهِ فِي شَيۡءٍ إِلَّآ أَن تَتَّقُواْ مِنۡهُمۡ تُقَىٰةٗۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ","aya_text_emlaey":"لا يتخذ المؤمنون الكافرين أولياء من دون المؤمنين ومن يفعل ذلك فليس من الله في شيء إلا أن تتقوا منهم تقاة ويحذركم الله نفسه وإلى الله المصير","aya_tafseer":"[28] ينهى الله المؤمنين أن يتخذوا الكافرين أولياء بالمحبة والنصرة من دون المؤمنين، ومَن يتولهم فقد برِئ من الله، والله بريء منه، إلَّا أن تكونوا ضعافاً خائفين فقد رخَّص الله لكم في مهادنتهم اتقاء لشرهم، حتى تقوى شوكتكم. ويحذركم الله نفسه، فاتقوه وخافوه. وإلى الله وحده رجوع الخلائق للحساب والجزاء."},{"id":"322","jozz":"3","page":"53","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"13","line_end":"15","aya_no":"29","aya_text":"قُلۡ إِن تُخۡفُواْ مَا فِي صُدُورِكُمۡ أَوۡ تُبۡدُوهُ يَعۡلَمۡهُ ٱللَّهُۗ وَيَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","aya_text_emlaey":"قل إن تخفوا ما في صدوركم أو تبدوه يعلمه الله ويعلم ما في السموات وما في الأرض والله على كل شيء قدير","aya_tafseer":"[29] قل -أيها النبي- للمؤمنين: إن تكتموا ما استقر في قلوبكم مِن موالاة الكافرين ونصرتهم أو تظهروا ذلك لا يَخْفَ على الله منه شيء، فإنَّ علمه محيط بكل ما في السموات وما في الأرض، وله القدرة التامة على كل شيء."},{"id":"323","jozz":"3","page":"54","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"3","aya_no":"30","aya_text":"يَوۡمَ تَجِدُ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ مِنۡ خَيۡرٖ مُّحۡضَرٗا وَمَا عَمِلَتۡ مِن سُوٓءٖ تَوَدُّ لَوۡ أَنَّ بَيۡنَهَا وَبَيۡنَهُۥٓ أَمَدَۢا بَعِيدٗاۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ","aya_text_emlaey":"يوم تجد كل نفس ما عملت من خير محضرا وما عملت من سوء تود لو أن بينها وبينه أمدا بعيدا ويحذركم الله نفسه والله رءوف بالعباد","aya_tafseer":"[30] وفي يوم القيامة يوم الجزاء تجد كل نفس ما عملت من خير ينتظرها موفراً لتُجزَىٰ به، وما عملت من عمل سيِّئ تجده في انتظارها أيضاً، فتتمنى لو أن بينها وبين هذا العمل زمناً بعيداً. فاستعدوا لهذا اليوم، وخافوا بطش الإله الجبار. ومع شدَّة عقابه فإنه سبحانه المتصف بكمال الرحمة بالعباد."},{"id":"324","jozz":"3","page":"54","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"3","line_end":"5","aya_no":"31","aya_text":"قُلۡ إِن كُنتُمۡ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِي يُحۡبِبۡكُمُ ٱللَّهُ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ","aya_text_emlaey":"قل إن كنتم تحبون الله فاتبعوني يحببكم الله ويغفر لكم ذنوبكم والله غفور رحيم","aya_tafseer":"[31] قل -أيها الرسول-: إن كنتم تحبون الله حقّاً فاتبعوني وآمنوا بي ظاهراً وباطناً، يحببكم الله، ويمْحُ ذنوبكم، فإنه غفور لذنوب عباده المؤمنين، رحيم بهم. وهذه الآية الكريمة حاكمة على كل من ادعى محبة الله -تعالى- وليس متبعاً لنبيه محمد -صلى الله عليه وسلم- حق الاتباع، مطيعاً له في أمره ونهيه، فإنه كاذب في دعواه حتى يتابع الرسول -صلى الله عليه وسلم- حق الاتباع."},{"id":"325","jozz":"3","page":"54","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"5","line_end":"6","aya_no":"32","aya_text":"قُلۡ أَطِيعُواْ ٱللَّهَ وَٱلرَّسُولَۖ فَإِن تَوَلَّوۡاْ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡكَٰفِرِينَ","aya_text_emlaey":"قل أطيعوا الله والرسول فإن تولوا فإن الله لا يحب الكافرين","aya_tafseer":"[32] قل -أيها الرسول-: أطيعوا الله باتباع كتابه، وأطيعوا الرسول باتباع سنته في حياته وبعد مماته، فإن هم أعرضوا عنك، وأصرُّوا على ما هم عليه مِن كفر وضلال، فليسوا أهلاً لمحبة الله؛ فإن الله لا يحب الكافرين."},{"id":"326","jozz":"3","page":"54","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"6","line_end":"7","aya_no":"33","aya_text":"۞ إِنَّ ٱللَّهَ ٱصۡطَفَىٰٓ ءَادَمَ وَنُوحٗا وَءَالَ إِبۡرَٰهِيمَ وَءَالَ عِمۡرَٰنَ عَلَى ٱلۡعَٰلَمِينَ","aya_text_emlaey":"إن الله اصطفى آدم ونوحا وآل إبراهيم وآل عمران على العالمين","aya_tafseer":"[33] إن الله اختار آدم ونوحاً وآل إبراهيم وآل عمران، وجعلهم أفضل أهل زمانهم."},{"id":"327","jozz":"3","page":"54","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"7","line_end":"8","aya_no":"34","aya_text":"ذُرِّيَّةَۢ بَعۡضُهَا مِنۢ بَعۡضٖۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ","aya_text_emlaey":"ذرية بعضها من بعض والله سميع عليم","aya_tafseer":"[34] هؤلاء الأنبياء والرسل سلسلة طُهْر متواصلة في الإخلاص لله وتوحيده والعمل بوحيه. والله سميع لأقوال عباده، عليم بأفعالهم، وسيجازيهم على ذلك."},{"id":"328","jozz":"3","page":"54","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"9","aya_no":"35","aya_text":"إِذۡ قَالَتِ ٱمۡرَأَتُ عِمۡرَٰنَ رَبِّ إِنِّي نَذَرۡتُ لَكَ مَا فِي بَطۡنِي مُحَرَّرٗا فَتَقَبَّلۡ مِنِّيٓۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","aya_text_emlaey":"إذ قالت امرأة عمران رب إني نذرت لك ما في بطني محررا فتقبل مني إنك أنت السميع العليم","aya_tafseer":"[35] اذكر -أيها الرسول- ما كان مِن أمر مريم وأمها وابنها عيسى عليه السلام؛ لتردَّ بذلك على من ادَّعَوا أُلوهية عيسى أو بنوَّته لله سبحانه، إذ قالت امرأة عمران حين حملت: يا ربِّ إني جعلت لك ما في بطني خالصاً لك، لخدمة «بيت المقدس»، فتقبَّل مني، إنك أنت وحدك السميع لدعائي، العليم بنيتي."},{"id":"329","jozz":"3","page":"54","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"10","line_end":"12","aya_no":"36","aya_text":"فَلَمَّا وَضَعَتۡهَا قَالَتۡ رَبِّ إِنِّي وَضَعۡتُهَآ أُنثَىٰ وَٱللَّهُ أَعۡلَمُ بِمَا وَضَعَتۡ وَلَيۡسَ ٱلذَّكَرُ كَٱلۡأُنثَىٰۖ وَإِنِّي سَمَّيۡتُهَا مَرۡيَمَ وَإِنِّيٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ","aya_text_emlaey":"فلما وضعتها قالت رب إني وضعتها أنثى والله أعلم بما وضعت وليس الذكر كالأنثى وإني سميتها مريم وإني أعيذها بك وذريتها من الشيطان الرجيم","aya_tafseer":"[36] فلما تمَّ حملها ووضعت مولودها قالت: ربِّ إني وضعتها أنثى لا تصلح للخدمة في «بيت المقدس» -والله أعلم بما وضعَتْ، وسوف يجعل الله لها شأناً- وقالت: وليس الذكر الذي أردت للخدمة كالأنثى في ذلك؛ لأن الذكر أقوى على الخدمة وأقْوَم بها، وإني سمَّيتها مريم، وإني حصَّنتها بك هي وذريَّتها من الشيطان المطرود من رحمتك."},{"id":"330","jozz":"3","page":"54","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"15","aya_no":"37","aya_text":"فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٖ وَأَنۢبَتَهَا نَبَاتًا حَسَنٗا وَكَفَّلَهَا زَكَرِيَّاۖ كُلَّمَا دَخَلَ عَلَيۡهَا زَكَرِيَّا ٱلۡمِحۡرَابَ وَجَدَ عِندَهَا رِزۡقٗاۖ قَالَ يَٰمَرۡيَمُ أَنَّىٰ لَكِ هَٰذَاۖ قَالَتۡ هُوَ مِنۡ عِندِ ٱللَّهِۖ إِنَّ ٱللَّهَ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٍ","aya_text_emlaey":"فتقبلها ربها بقبول حسن وأنبتها نباتا حسنا وكفلها زكريا كلما دخل عليها زكريا المحراب وجد عندها رزقا قال يامريم أنى لك هذا قالت هو من عند الله إن الله يرزق من يشاء بغير حساب","aya_tafseer":"[37] فاستجاب الله دعاءها وقبل منها نَذْرها أحسن قَبول، وتولَّى ابنتها مريم بالرعاية فأنبتها نباتاً حسناً، ويسَّر الله لها زكريا عليه السلام كافلاً، فأسكنها في مكان عبادته، وكان كلَّما دخل عليها هذا المكان وجد عندها رزقاً هنيئاً معدّاً قال: يا مريم مِن أين لكِ هذا الرزق الطيب؟ قالت: هو رزق من عند الله. إن الله -بفضله- يرزق مَن يشاء مِن خلقه بغير حساب."},{"id":"331","jozz":"3","page":"55","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"2","aya_no":"38","aya_text":"هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥۖ قَالَ رَبِّ هَبۡ لِي مِن لَّدُنكَ ذُرِّيَّةٗ طَيِّبَةًۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ","aya_text_emlaey":"هنالك دعا زكريا ربه قال رب هب لي من لدنك ذرية طيبة إنك سميع الدعاء","aya_tafseer":"[38] عندما رأى زكريا ما أكرم الله به مريم مِن رزقه وفضله توجه إلى ربه قائلاً: يا ربِّ أعطني من عندك ولداً صالحاً مباركاً، إنك سميع الدعاء لمن دعاك."},{"id":"332","jozz":"3","page":"55","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"2","line_end":"4","aya_no":"39","aya_text":"فَنَادَتۡهُ ٱلۡمَلَٰٓئِكَةُ وَهُوَ قَآئِمٞ يُصَلِّي فِي ٱلۡمِحۡرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحۡيَىٰ مُصَدِّقَۢا بِكَلِمَةٖ مِّنَ ٱللَّهِ وَسَيِّدٗا وَحَصُورٗا وَنَبِيّٗا مِّنَ ٱلصَّٰلِحِينَ","aya_text_emlaey":"فنادته الملائكة وهو قائم يصلي في المحراب أن الله يبشرك بيحيى مصدقا بكلمة من الله وسيدا وحصورا ونبيا من الصالحين","aya_tafseer":"[39] فنادته الملائكة وهو واقف بين يدي الله في مكان صلاته يدعوه: أن الله يخبرك بخبر يسرُّك، وهو أنك ستُرزَق بولد اسمه يحيى، يُصَدِّق بكلمة من الله -وهو عيسى بن مريم عليه السلام-، ويكون يحيى سيداً في قومه، له المكانة والمنزلة العالية، وحصوراً لا يأتي الذنوب والشهوات الضارة، ويكون نبيّاً من الصالحين الذين بلغوا في الصَّلاح ذروته ."},{"id":"333","jozz":"3","page":"55","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"4","line_end":"6","aya_no":"40","aya_text":"قَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَقَدۡ بَلَغَنِيَ ٱلۡكِبَرُ وَٱمۡرَأَتِي عَاقِرٞۖ قَالَ كَذَٰلِكَ ٱللَّهُ يَفۡعَلُ مَا يَشَآءُ","aya_text_emlaey":"قال رب أنى يكون لي غلام وقد بلغني الكبر وامرأتي عاقر قال كذلك الله يفعل ما يشاء","aya_tafseer":"[40] قال زكريا فرحاً متعجباً: ربِّ أنَّى يكون لي غلام مع أن الشيخوخة قد بلغت مني مبلغها، وامرأتي عقيم لا تلد؟ قال: كذلكَ يفعل الله ما يشاء من الأفعال العجيبة المخالفة للعادة."},{"id":"334","jozz":"3","page":"55","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"6","line_end":"8","aya_no":"41","aya_text":"قَالَ رَبِّ ٱجۡعَل لِّيٓ ءَايَةٗۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَةَ أَيَّامٍ إِلَّا رَمۡزٗاۗ وَٱذۡكُر رَّبَّكَ كَثِيرٗا وَسَبِّحۡ بِٱلۡعَشِيِّ وَٱلۡإِبۡكَٰرِ","aya_text_emlaey":"قال رب اجعل لي آية قال آيتك ألا تكلم الناس ثلاثة أيام إلا رمزا واذكر ربك كثيرا وسبح بالعشي والإبكار","aya_tafseer":"[41] قال زكريَّا: رب اجعل لي علامةً أستدلُّ بها على وجود الولد منِّي؛ ليحصل لي السرور والاستبشار، قال: علامتك التي طلبتها: ألَّا تستطيع التحدث إلى الناس ثلاثة أيام إلَّا بإشارة إليهم، مع أنك سويٌّ صحيح، وفي هذه المدة أكثِرْ من ذكر ربك، وصلِّ له أواخر النهار وأوائله."},{"id":"335","jozz":"3","page":"55","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"10","aya_no":"42","aya_text":"وَإِذۡ قَالَتِ ٱلۡمَلَٰٓئِكَةُ يَٰمَرۡيَمُ إِنَّ ٱللَّهَ ٱصۡطَفَىٰكِ وَطَهَّرَكِ وَٱصۡطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"وإذ قالت الملائكة يامريم إن الله اصطفاك وطهرك واصطفاك على نساء العالمين","aya_tafseer":"[42] واذكر -أيها الرسول- حين قالت الملائكة: يا مريم إن الله اختاركِ لطاعته وطَهَّركِ من الأخلاق الرذيلة، واختاركِ على نساء العالمين في زمانك."},{"id":"336","jozz":"3","page":"55","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"10","line_end":"11","aya_no":"43","aya_text":"يَٰمَرۡيَمُ ٱقۡنُتِي لِرَبِّكِ وَٱسۡجُدِي وَٱرۡكَعِي مَعَ ٱلرَّٰكِعِينَ","aya_text_emlaey":"يامريم اقنتي لربك واسجدي واركعي مع الراكعين","aya_tafseer":"[43] يا مريم داومي على الطاعة لربك، وقومي في خشوع وتواضع، واسجدي واركعي مع الراكعين؛ شكراً لله على ما أولاكِ من نعمه."},{"id":"337","jozz":"3","page":"55","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"11","line_end":"13","aya_no":"44","aya_text":"ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهِ إِلَيۡكَۚ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يُلۡقُونَ أَقۡلَٰمَهُمۡ أَيُّهُمۡ يَكۡفُلُ مَرۡيَمَ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يَخۡتَصِمُونَ","aya_text_emlaey":"ذلك من أنباء الغيب نوحيه إليك وما كنت لديهم إذ يلقون أقلامهم أيهم يكفل مريم وما كنت لديهم إذ يختصمون","aya_tafseer":"[44] ذلك الذي قصصناه عليك -أيها الرسول- من أخبار الغيب التي أوحاها الله إليك، إذ لم تكن معهم حين اختلفوا في كفالة مريم أيُّهم أحق بها وأولى، ووقع بينهم الخصام، فأجْرَوْا القرعة بإلقاء أقلامهم، فأصابت زكريا عليه السلام، ففاز بكفالتها."},{"id":"338","jozz":"3","page":"55","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"13","line_end":"15","aya_no":"45","aya_text":"إِذۡ قَالَتِ ٱلۡمَلَٰٓئِكَةُ يَٰمَرۡيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٖ مِّنۡهُ ٱسۡمُهُ ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ وَجِيهٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمِنَ ٱلۡمُقَرَّبِينَ","aya_text_emlaey":"إذ قالت الملائكة يامريم إن الله يبشرك بكلمة منه اسمه المسيح عيسى ابن مريم وجيها في الدنيا والآخرة ومن المقربين","aya_tafseer":"[45] وما كنت -يا نبي الله- هناك حين قالت الملائكة: يا مريم إن الله يُبشِّركِ بولد يكون وجوده بكلمة من الله، أي يقول له: «كن»، فيكون، اسمه المسيح عيسى بن مريم، له الجاه العظيم في الدنيا والآخرة، ومن المقربين عند الله يوم القيامة."},{"id":"339","jozz":"3","page":"56","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"1","aya_no":"46","aya_text":"وَيُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗا وَمِنَ ٱلصَّٰلِحِينَ","aya_text_emlaey":"ويكلم الناس في المهد وكهلا ومن الصالحين","aya_tafseer":"[46] ويكلم الناس وهو رضيع قبل أوان الكلام، ويدعوهم إلى الله وهو كبير قد اجتمعت قوَّته وكمُل شبابه بما أوحاه الله إليه. وهذا تكليم النبوَّة والدعوة والإرشاد، وهو معدود من أهل الصلاح والفضل في قوله وعمله."},{"id":"340","jozz":"3","page":"56","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"2","line_end":"3","aya_no":"47","aya_text":"قَالَتۡ رَبِّ أَنَّىٰ يَكُونُ لِي وَلَدٞ وَلَمۡ يَمۡسَسۡنِي بَشَرٞۖ قَالَ كَذَٰلِكِ ٱللَّهُ يَخۡلُقُ مَا يَشَآءُۚ إِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ","aya_text_emlaey":"قالت رب أنى يكون لي ولد ولم يمسسني بشر قال كذلك الله يخلق ما يشاء إذا قضى أمرا فإنما يقول له كن فيكون","aya_tafseer":"[47] قالت مريم متعجبة من هذا الأمر: أنَّى يكون لي ولد وأنا لست بذات زوج ولا بَغِيٍّ؟ قال لها المَلَك: هذا الذي يحدث لكِ ليس بمستبعد على الإله القادر، الذي يوجِد ما يشاء من العدم، فإذا أراد إيجاد شيء فإنما يقول له: «كُن» فيكون."},{"id":"341","jozz":"3","page":"56","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"4","line_end":"4","aya_no":"48","aya_text":"وَيُعَلِّمُهُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ","aya_text_emlaey":"ويعلمه الكتاب والحكمة والتوراة والإنجيل","aya_tafseer":"[48] ويعلمه الكتابة، والسداد في القول والفعل، والتوراة التي أوحاها الله إلى موسى عليه السلام، والإنجيل الذي أنزل الله عليه."},{"id":"342","jozz":"3","page":"56","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"5","line_end":"9","aya_no":"49","aya_text":"وَرَسُولًا إِلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ أَنِّي قَدۡ جِئۡتُكُم بِـَٔايَةٖ مِّن رَّبِّكُمۡ أَنِّيٓ أَخۡلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيۡرَۢا بِإِذۡنِ ٱللَّهِۖ وَأُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ وَأُحۡيِ ٱلۡمَوۡتَىٰ بِإِذۡنِ ٱللَّهِۖ وَأُنَبِّئُكُم بِمَا تَأۡكُلُونَ وَمَا تَدَّخِرُونَ فِي بُيُوتِكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ","aya_text_emlaey":"ورسولا إلى بني إسرائيل أني قد جئتكم بآية من ربكم أني أخلق لكم من الطين كهيئة الطير فأنفخ فيه فيكون طيرا بإذن الله وأبرئ الأكمه والأبرص وأحي الموتى بإذن الله وأنبئكم بما تأكلون وما تدخرون في بيوتكم إن في ذلك لآية لكم إن كنتم مؤمنين","aya_tafseer":"[49] ويجعله رسولاً إلى بني إسرائيل، ويقول لهم: إني قد جئتكم بعلامة من ربكم تدلُّ على أني مرسل من الله، وهي أني أصنع لكم من الطين مثل شكل الطير، فأنفخ فيه فيكون طيراً حقيقيّاً بإذن الله، وأَشفي مَن وُلِد أعمى، ومَن به برص، وأُحيي مَن كان ميتاً بإذن الله، وأخبركم بما تأكلون وتدَّخرون في بيوتكم من طعامكم. إن في هذه الأمور العظيمة التي ليست في قدرة البشر لدليلاً على أني نبي الله ورسوله، إن كنتم مصدِّقين حجج الله وآياته، مقرِّين بتوحيده."},{"id":"343","jozz":"3","page":"56","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"10","line_end":"12","aya_no":"50","aya_text":"وَمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيَّ مِنَ ٱلتَّوۡرَىٰةِ وَلِأُحِلَّ لَكُم بَعۡضَ ٱلَّذِي حُرِّمَ عَلَيۡكُمۡۚ وَجِئۡتُكُم بِـَٔايَةٖ مِّن رَّبِّكُمۡ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ","aya_text_emlaey":"ومصدقا لما بين يدي من التوراة ولأحل لكم بعض الذي حرم عليكم وجئتكم بآية من ربكم فاتقوا الله وأطيعون","aya_tafseer":"[50] وجئتكم مصدقاً بما في التوراة، ولأحلَّ لكم بوحي من الله بعض ما حرَّمه الله عليكم تخفيفاً من الله ورحمة، وجئتكم بحجة من ربكم على صدق ما أقول لكم، فاتقوا الله ولا تخالفوا أمره، وأطيعوني فيما أبلغكم به عن الله."},{"id":"344","jozz":"3","page":"56","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"13","aya_no":"51","aya_text":"إِنَّ ٱللَّهَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ","aya_text_emlaey":"إن الله ربي وربكم فاعبدوه هذا صراط مستقيم","aya_tafseer":"[51] إن الله الذي أدعوكم إليه هو وحده ربي وربكم فاعبدوه، فأنا وأنتم سواء في العبودية والخضوع له، وهذا هو الطريق الذي لا اعوجاج فيه."},{"id":"345","jozz":"3","page":"56","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"13","line_end":"15","aya_no":"52","aya_text":"۞ فَلَمَّآ أَحَسَّ عِيسَىٰ مِنۡهُمُ ٱلۡكُفۡرَ قَالَ مَنۡ أَنصَارِيٓ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِيُّونَ نَحۡنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشۡهَدۡ بِأَنَّا مُسۡلِمُونَ","aya_text_emlaey":"فلما أحس عيسى منهم الكفر قال من أنصاري إلى الله قال الحواريون نحن أنصار الله آمنا بالله واشهد بأنا مسلمون","aya_tafseer":"[52] فلما استشعر عيسى منهم التصميم على الكفر نادى في أصحابه الخُلَّص: مَن يكون معي في نصرة دين الله؟ قال أصفياء عيسى: نحن أنصار دين الله والداعون إليه، صدَّقنا بالله واتبعناك، واشهد أنت يا عيسى بأنا مستسلمون لله بالتوحيد والطاعة."},{"id":"346","jozz":"3","page":"57","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"2","aya_no":"53","aya_text":"رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلۡتَ وَٱتَّبَعۡنَا ٱلرَّسُولَ فَٱكۡتُبۡنَا مَعَ ٱلشَّٰهِدِينَ","aya_text_emlaey":"ربنا آمنا بما أنـزلت واتبعنا الرسول فاكتبنا مع الشاهدين","aya_tafseer":"[53] ربنا صدَّقنا بما أنزلت من الإنجيل، واتبعنا رسولك عيسى عليه السلام، فاجعلنا ممن شهدوا لك بالوحدانية ولأنبيائك بالرسالة، وهم أمة محمد -صلى الله عليه وسلم- الذين يشهدون للرسل بأنهم بلَّغوا أممهم."},{"id":"347","jozz":"3","page":"57","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"2","line_end":"2","aya_no":"54","aya_text":"وَمَكَرُواْ وَمَكَرَ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ","aya_text_emlaey":"ومكروا ومكر الله والله خير الماكرين","aya_tafseer":"[54] ومكر الذين كفروا من بني إسرائيل بعيسى عليه السلام، بأن وكَّلوا به مَن يقتله غِيْلة، فألقى الله شَبَه عيسى على رجل دلَّهم عليه فأمسكوا به، وقتلوه وصلبوه ظنّاً منهم أنه عيسى عليه السلام، والله خير الماكرين. وفي هذا إثبات صفة المكر لله -تعالى- على ما يليق بجلاله وكماله؛ لأنه مكر بحق، وفي مقابلة مكر الماكرين."},{"id":"348","jozz":"3","page":"57","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"3","line_end":"6","aya_no":"55","aya_text":"إِذۡ قَالَ ٱللَّهُ يَٰعِيسَىٰٓ إِنِّي مُتَوَفِّيكَ وَرَافِعُكَ إِلَيَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُواْ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوۡقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِۖ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأَحۡكُمُ بَيۡنَكُمۡ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ","aya_text_emlaey":"إذ قال الله ياعيسى إني متوفيك ورافعك إلي ومطهرك من الذين كفروا وجاعل الذين اتبعوك فوق الذين كفروا إلى يوم القيامة ثم إلي مرجعكم فأحكم بينكم فيما كنتم فيه تختلفون","aya_tafseer":"[55] ومكر الله بهم حين قال الله لعيسى: إني قابضك من الأرض مِن غير أن ينالك سوء، ورافعك إليَّ ببدنك وروحك، ومخلصك من الذين كفروا بك، وجاعل الذين اتبعوك -أي: على دينك وما جئت به عن الله من الدين والبشارة بمحمد -صلى الله عليه وسلم- وآمَنوا بمحمد -صلى الله عليه وسلم-، بعد بعثته، والتزموا شريعته- ظاهرين على الذين جحدوا نبوتك إلى يوم القيامة، ثم إليَّ مصيركم جميعاً يوم الحساب، فأفصِل بينكم فيما كنتم فيه تختلفون من أمر عيسى عليه السلام."},{"id":"349","jozz":"3","page":"57","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"6","line_end":"8","aya_no":"56","aya_text":"فَأَمَّا ٱلَّذِينَ كَفَرُواْ فَأُعَذِّبُهُمۡ عَذَابٗا شَدِيدٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ","aya_text_emlaey":"فأما الذين كفروا فأعذبهم عذابا شديدا في الدنيا والآخرة وما لهم من ناصرين","aya_tafseer":"[56] فأمَّا الذين كفروا بالمسيح من اليهود أو غَلَوا فيه من النصارى، فأعذبهم عذاباً شديداً في الدنيا: بالقتل وسَلْبِ الأموال وإزالة الملك، وفي الآخرة بالنار، ومالهم مِن ناصر ينصرهم ويدفع عنهم عذاب الله."},{"id":"350","jozz":"3","page":"57","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"9","aya_no":"57","aya_text":"وَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمۡ أُجُورَهُمۡۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ","aya_text_emlaey":"وأما الذين آمنوا وعملوا الصالحات فيوفيهم أجورهم والله لا يحب الظالمين","aya_tafseer":"[57] وأما الذين آمنوا بالله ورسله وعملوا الأعمال الصالحة، فيعطيهم الله ثواب أعمالهم كاملاً غير منقوص. والله لا يُحب الظالمين بالشرك والكفر."},{"id":"351","jozz":"3","page":"57","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"9","line_end":"10","aya_no":"58","aya_text":"ذَٰلِكَ نَتۡلُوهُ عَلَيۡكَ مِنَ ٱلۡأٓيَٰتِ وَٱلذِّكۡرِ ٱلۡحَكِيمِ","aya_text_emlaey":"ذلك نتلوه عليك من الآيات والذكر الحكيم","aya_tafseer":"[58] ذلك الذي نقصُّه عليك في شأن عيسى، من الدلائل الواضحة على صحة رسالتك، وصحة القرآن الحكيم الذي يفصل بين الحق والباطل، فلا شك فيه ولا امتراء."},{"id":"352","jozz":"3","page":"57","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"10","line_end":"12","aya_no":"59","aya_text":"إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَۖ خَلَقَهُۥ مِن تُرَابٖ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ","aya_text_emlaey":"إن مثل عيسى عند الله كمثل آدم خلقه من تراب ثم قال له كن فيكون","aya_tafseer":"[59] إنَّ خَلْقَ الله لعيسى من غير أب مثَلُه كمثل خلق الله لآدم من غير أب ولا أم؛ إذ خلقه من تراب الأرض، ثم قال له: «كن بشراً» فكان. فدعوى إلهية عيسى لكونه خلق من غير أب دعوى باطلة؛ فآدم عليه السلام خلق من غير أب ولا أم، واتفق الجميع على أنه عَبْد من عباد الله."},{"id":"353","jozz":"3","page":"57","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"12","aya_no":"60","aya_text":"ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلۡمُمۡتَرِينَ","aya_text_emlaey":"الحق من ربك فلا تكن من الممترين","aya_tafseer":"[60] الحق الذي لا شك فيه في أمر عيسى هو الذي جاءك -أيها الرسول- من ربك، فَدُمْ على يقينك، وعلى ما أنت عليه من ترك الافتراء، ولا تكن من الشاكِّين. وفي هذا تثبيت وطمأنة لرسول الله -صلى الله عليه وسلم-."},{"id":"354","jozz":"3","page":"57","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"13","line_end":"15","aya_no":"61","aya_text":"فَمَنۡ حَآجَّكَ فِيهِ مِنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ فَقُلۡ تَعَالَوۡاْ نَدۡعُ أَبۡنَآءَنَا وَأَبۡنَآءَكُمۡ وَنِسَآءَنَا وَنِسَآءَكُمۡ وَأَنفُسَنَا وَأَنفُسَكُمۡ ثُمَّ نَبۡتَهِلۡ فَنَجۡعَل لَّعۡنَتَ ٱللَّهِ عَلَى ٱلۡكَٰذِبِينَ","aya_text_emlaey":"فمن حاجك فيه من بعد ما جاءك من العلم فقل تعالوا ندع أبناءنا وأبناءكم ونساءنا ونساءكم وأنفسنا وأنفسكم ثم نبتهل فنجعل لعنة الله على الكاذبين","aya_tafseer":"[61] فمَن جادلك -أيها الرسول- في المسيح عيسى بن مريم، من بعد ما جاءك من العلم في أمر عيسى عليه السلام، فقل لهم: تعالوا نُحْضِر أبناءنا وأبناءكم، ونساءنا ونساءكم، وأنفسنا وأنفسكم، ثم نتجه إلى الله بالدعاء أن يُنزل عقوبته ولعنته على الكاذبين في قولهم، المصرِّين على عنادهم."},{"id":"355","jozz":"3","page":"58","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"2","aya_no":"62","aya_text":"إِنَّ هَٰذَا لَهُوَ ٱلۡقَصَصُ ٱلۡحَقُّۚ وَمَا مِنۡ إِلَٰهٍ إِلَّا ٱللَّهُۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ","aya_text_emlaey":"إن هذا لهو القصص الحق وما من إله إلا الله وإن الله لهو العزيز الحكيم","aya_tafseer":"[62] إن هذا الذي أنبأتك به -أيها الرسول- من أمر عيسى لهو النبأ الحق الذي لا شك فيه، وما من معبود يستحق العبادة إلا الله وحده، وإن الله لهو العزيز في ملكه، الحكيم في تدبيره وفعله."},{"id":"356","jozz":"3","page":"58","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"2","line_end":"2","aya_no":"63","aya_text":"فَإِن تَوَلَّوۡاْ فَإِنَّ ٱللَّهَ عَلِيمُۢ بِٱلۡمُفۡسِدِينَ","aya_text_emlaey":"فإن تولوا فإن الله عليم بالمفسدين","aya_tafseer":"[63] فإن أعرضوا عن تصديقك واتباعك فهم المفسدون، والله عليم بهم، وسيجازيهم على ذلك."},{"id":"357","jozz":"3","page":"58","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"3","line_end":"6","aya_no":"64","aya_text":"قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةٖ سَوَآءِۭ بَيۡنَنَا وَبَيۡنَكُمۡ أَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ وَلَا نُشۡرِكَ بِهِۦ شَيۡـٔٗا وَلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابٗا مِّن دُونِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَقُولُواْ ٱشۡهَدُواْ بِأَنَّا مُسۡلِمُونَ","aya_text_emlaey":"قل ياأهل الكتاب تعالوا إلى كلمة سواء بيننا وبينكم ألا نعبد إلا الله ولا نشرك به شيئا ولا يتخذ بعضنا بعضا أربابا من دون الله فإن تولوا فقولوا اشهدوا بأنا مسلمون","aya_tafseer":"[64] قل -أيها الرسول- لأهل الكتاب من اليهود والنصارى: تعالَوْا إلى كلمة عدل وحق نلتزم بها جميعاً: وهي أن نَخُص الله وحده بالعبادة، ولا نتخذ أي شريك معه، من وثن أو صنم أو صليب أو طاغوت أو غير ذلك، ولا يدين بعضنا لبعض بالطاعة من دون الله. فإن أعرضوا عن هذه الدعوة الطيبة فقولوا لهم -أيها المؤمنون-: اشهدوا علينا بأنا مسلمون منقادون لربنا بالعبودية والإخلاص. والدعوة إلى كلمة سواء، كما تُوجَّه إلى اليهود والنصارى، تُوجَّه إلى من جرى مجراهم."},{"id":"358","jozz":"3","page":"58","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"6","line_end":"7","aya_no":"65","aya_text":"يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تُحَآجُّونَ فِيٓ إِبۡرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوۡرَىٰةُ وَٱلۡإِنجِيلُ إِلَّا مِنۢ بَعۡدِهِۦٓۚ أَفَلَا تَعۡقِلُونَ","aya_text_emlaey":"ياأهل الكتاب لم تحاجون في إبراهيم وما أنـزلت التوراة والإنجيل إلا من بعده أفلا تعقلون","aya_tafseer":"[65] يا أصحاب الكتب المنزلة، من اليهود والنصارى، كيف يجادل كل منكم في أن إبراهيم عليه السلام كان على ملَّته، وما أُنزلت التوراة والإنجيل إلا من بعده؟ أفلا تفقهون خطأ قولكم: إن إبراهيم كان يهوديّاً أو نصرانيّاً، وقد علمتم أن اليهودية والنصرانية حدثت بعد وفاته بحين؟"},{"id":"359","jozz":"3","page":"58","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"10","aya_no":"66","aya_text":"هَٰٓأَنتُمۡ هَٰٓؤُلَآءِ حَٰجَجۡتُمۡ فِيمَا لَكُم بِهِۦ عِلۡمٞ فَلِمَ تُحَآجُّونَ فِيمَا لَيۡسَ لَكُم بِهِۦ عِلۡمٞۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ","aya_text_emlaey":"ها أنتم هؤلاء حاججتم فيما لكم به علم فلم تحاجون فيما ليس لكم به علم والله يعلم وأنتم لا تعلمون","aya_tafseer":"[66] ها أنتم يا هؤلاء جادلتم رسول الله محمداً -صلى الله عليه وسلم- فيما لكم به علم مِن أمر دينكم، مما تعتقدون صحته في كتبكم، فلِمَ تجادلون فيما ليس لكم به علم من أمر إبراهيم؟ والله يعلم الأمور على خفائها، وأنتم لا تعلمون."},{"id":"360","jozz":"3","page":"58","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"10","line_end":"11","aya_no":"67","aya_text":"مَا كَانَ إِبۡرَٰهِيمُ يَهُودِيّٗا وَلَا نَصۡرَانِيّٗا وَلَٰكِن كَانَ حَنِيفٗا مُّسۡلِمٗا وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ","aya_text_emlaey":"ما كان إبراهيم يهوديا ولا نصرانيا ولكن كان حنيفا مسلما وما كان من المشركين","aya_tafseer":"[67] ما كان إبراهيم يهوديّاً ولا نصرانيّاً، فلم تكن اليهودية ولا النصرانية إلا من بعده، ولكن كان متبعاً لأمر الله وطاعته، مستسلماً لربه، وما كان من المشركين."},{"id":"361","jozz":"3","page":"58","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"13","aya_no":"68","aya_text":"إِنَّ أَوۡلَى ٱلنَّاسِ بِإِبۡرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَٰذَا ٱلنَّبِيُّ وَٱلَّذِينَ ءَامَنُواْۗ وَٱللَّهُ وَلِيُّ ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"إن أولى الناس بإبراهيم للذين اتبعوه وهذا النبي والذين آمنوا والله ولي المؤمنين","aya_tafseer":"[68] إنَّ أحق الناس بإبراهيم وأخصهم به، الذين آمنوا به وصدقوا برسالته واتبعوه على دينه، وهذا النبي محمد -صلى الله عليه وسلم- والذين آمنوا به. والله وليُّ المؤمنين به المتبعين شرعه."},{"id":"362","jozz":"3","page":"58","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"13","line_end":"14","aya_no":"69","aya_text":"وَدَّت طَّآئِفَةٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ لَوۡ يُضِلُّونَكُمۡ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ","aya_text_emlaey":"ودت طائفة من أهل الكتاب لو يضلونكم وما يضلون إلا أنفسهم وما يشعرون","aya_tafseer":"[69] تمنَّتْ جماعة من اليهود والنصارى لو يضلونكم -أيها المسلمون- عن الإسلام، وما يضلون إلا أنفسهم وأتباعهم، وما يدرون ذلك ولا يعلمونه."},{"id":"363","jozz":"3","page":"58","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"14","line_end":"15","aya_no":"70","aya_text":"يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَأَنتُمۡ تَشۡهَدُونَ","aya_text_emlaey":"ياأهل الكتاب لم تكفرون بآيات الله وأنتم تشهدون","aya_tafseer":"[70] يا أهل التوراة والإنجيل لِمَ تجحدون آيات الله التي أنزلها على رسله في كتبكم، وفيها أن محمداً -صلى الله عليه وسلم- هو الرسول المنتظر، وأن ما جاءكم به هو الحق، وأنتم تشهدون بذلك؟ ولكنكم تنكرونه."},{"id":"364","jozz":"3","page":"59","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"2","aya_no":"71","aya_text":"يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَلۡبِسُونَ ٱلۡحَقَّ بِٱلۡبَٰطِلِ وَتَكۡتُمُونَ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ","aya_text_emlaey":"ياأهل الكتاب لم تلبسون الحق بالباطل وتكتمون الحق وأنتم تعلمون","aya_tafseer":"[71] يا أهل التوراة والإنجيل لِمَ تخلطون الحق في كتبكم بما حرفتموه وكتبتموه من الباطل بأيديكم، وتُخْفون ما فيهما من صفة محمد -صلى الله عليه وسلم-، وأن دينه هو الحق، وأنتم تعلمون ذلك؟"},{"id":"365","jozz":"3","page":"59","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"2","line_end":"4","aya_no":"72","aya_text":"وَقَالَت طَّآئِفَةٞ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ ءَامِنُواْ بِٱلَّذِيٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَجۡهَ ٱلنَّهَارِ وَٱكۡفُرُوٓاْ ءَاخِرَهُۥ لَعَلَّهُمۡ يَرۡجِعُونَ","aya_text_emlaey":"وقالت طائفة من أهل الكتاب آمنوا بالذي أنـزل على الذين آمنوا وجه النهار واكفروا آخره لعلهم يرجعون","aya_tafseer":"[72] وقالت جماعة من أهل الكتاب من اليهود: صدِّقوا بالذي أُنزل على الذين آمنوا أول النهار واكفروا آخره؛ لعلهم يتشككون في دينهم، ويرجعون عنه."},{"id":"366","jozz":"3","page":"59","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"4","line_end":"7","aya_no":"73","aya_text":"وَلَا تُؤۡمِنُوٓاْ إِلَّا لِمَن تَبِعَ دِينَكُمۡ قُلۡ إِنَّ ٱلۡهُدَىٰ هُدَى ٱللَّهِ أَن يُؤۡتَىٰٓ أَحَدٞ مِّثۡلَ مَآ أُوتِيتُمۡ أَوۡ يُحَآجُّوكُمۡ عِندَ رَبِّكُمۡۗ قُلۡ إِنَّ ٱلۡفَضۡلَ بِيَدِ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ","aya_text_emlaey":"ولا تؤمنوا إلا لمن تبع دينكم قل إن الهدى هدى الله أن يؤتى أحد مثل ما أوتيتم أو يحاجوكم عند ربكم قل إن الفضل بيد الله يؤتيه من يشاء والله واسع عليم","aya_tafseer":"[73] ولا تصدِّقوا تصديقاً صحيحاً إلا لِمَن تبع دينكم فكان يهوديّاً، قل لهم -أيها الرسول-: إن الهدى والتوفيق هدى الله وتوفيقه للإيمان الصحيح. وقالوا: لا تظهروا ما عندكم من العلم للمسلمين فيتعلموه منكم فيساووكم في العلم به، وتكون لهم الأفضلية عليكم، أو أن يتخذوه حجة عند ربكم يغلبونكم بها. قل لهم -أيها الرسول-: إن الفضل والعطاء والأمور كلها بيد الله وتحت تصرفه، يؤتيها مَن يشاء ممن آمن به وبرسوله. والله واسع عليم، يَسَعُ بعلمه وعطائه جميع مخلوقاته، ممن يستحق فضله ونعمه."},{"id":"367","jozz":"3","page":"59","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"7","line_end":"8","aya_no":"74","aya_text":"يَخۡتَصُّ بِرَحۡمَتِهِۦ مَن يَشَآءُۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ","aya_text_emlaey":"يختص برحمته من يشاء والله ذو الفضل العظيم","aya_tafseer":"[74] إن الله يختص مِن خلقه مَن يشاء بالنبوة والهداية إلى أكمل الشرائع. والله ذو الإحسان والعطاء الكثير الواسع."},{"id":"368","jozz":"3","page":"59","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"11","aya_no":"75","aya_text":"۞ وَمِنۡ أَهۡلِ ٱلۡكِتَٰبِ مَنۡ إِن تَأۡمَنۡهُ بِقِنطَارٖ يُؤَدِّهِۦٓ إِلَيۡكَ وَمِنۡهُم مَّنۡ إِن تَأۡمَنۡهُ بِدِينَارٖ لَّا يُؤَدِّهِۦٓ إِلَيۡكَ إِلَّا مَا دُمۡتَ عَلَيۡهِ قَآئِمٗاۗ ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَيۡسَ عَلَيۡنَا فِي ٱلۡأُمِّيِّـۧنَ سَبِيلٞ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ","aya_text_emlaey":"ومن أهل الكتاب من إن تأمنه بقنطار يؤده إليك ومنهم من إن تأمنه بدينار لا يؤده إليك إلا ما دمت عليه قائما ذلك بأنهم قالوا ليس علينا في الأميين سبيل ويقولون على الله الكذب وهم يعلمون","aya_tafseer":"[75] ومن أهل الكتاب من اليهود مَن إنْ تأمنه على كثير من المال يؤدِّه إليك من غير خيانة، ومنهم مَن إنْ تأمنه على دينار واحد لا يؤدِّه إليك، إلا إذا بذلت غاية الجهد في مطالبته. وسبب ذلك عقيدة فاسدة تجعلهم يستحلُّون أموال العرب بالباطل، ويقولون: ليس علينا في أكل أموالهم إثم ولا حرج؛ لأن الله أحلَّها لنا. وهذا كذب على الله، يقولونه بألسنتهم، وهم يعلمون أنهم كاذبون."},{"id":"369","jozz":"3","page":"59","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"12","aya_no":"76","aya_text":"بَلَىٰۚ مَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ","aya_text_emlaey":"بلى من أوفى بعهده واتقى فإن الله يحب المتقين","aya_tafseer":"[76] ليس الأمر كما زعم هؤلاء الكاذبون، فإن المتقي حقّاً هو من أوفى بما عاهد الله عليه من أداء الأمانة والإيمان به وبرسله والتزم هديه وشرعه، وخاف الله عز وجل فامتثل أمره وانتهى عما نهى عنه. والله يحب المتقين الذين يتقون الشرك والمعاصي."},{"id":"370","jozz":"3","page":"59","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"13","line_end":"15","aya_no":"77","aya_text":"إِنَّ ٱلَّذِينَ يَشۡتَرُونَ بِعَهۡدِ ٱللَّهِ وَأَيۡمَٰنِهِمۡ ثَمَنٗا قَلِيلًا أُوْلَٰٓئِكَ لَا خَلَٰقَ لَهُمۡ فِي ٱلۡأٓخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ إِلَيۡهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٞ","aya_text_emlaey":"إن الذين يشترون بعهد الله وأيمانهم ثمنا قليلا أولئك لا خلاق لهم في الآخرة ولا يكلمهم الله ولا ينظر إليهم يوم القيامة ولا يزكيهم ولهم عذاب أليم","aya_tafseer":"[77] إن الذين يستبدلون بعهد الله ووصيته التي أوصى بها في الكتب التي أنزلها على أنبيائهم، عوضاً وبدلاً خسيساً من عرض الدنيا وحطامها، أولئك لا نصيب لهم من الثواب في الآخرة، ولا يكلمهم الله بما يَسُرُّهم، ولا ينظر إليهم يوم القيامة بعين الرحمة، ولا يطهرهم من دنس الذنوب والكفر، ولهم عذاب موجع."},{"id":"371","jozz":"3","page":"60","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"4","aya_no":"78","aya_text":"وَإِنَّ مِنۡهُمۡ لَفَرِيقٗا يَلۡوُۥنَ أَلۡسِنَتَهُم بِٱلۡكِتَٰبِ لِتَحۡسَبُوهُ مِنَ ٱلۡكِتَٰبِ وَمَا هُوَ مِنَ ٱلۡكِتَٰبِ وَيَقُولُونَ هُوَ مِنۡ عِندِ ٱللَّهِ وَمَا هُوَ مِنۡ عِندِ ٱللَّهِۖ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ","aya_text_emlaey":"وإن منهم لفريقا يلوون ألسنتهم بالكتاب لتحسبوه من الكتاب وما هو من الكتاب ويقولون هو من عند الله وما هو من عند الله ويقولون على الله الكذب وهم يعلمون","aya_tafseer":"[78] وإن مِن اليهود لَجماعةً يحرفون الكلام عن مواضعه، ويبدلون كلام الله؛ ليوهموا غيرهم أن هذا من الكلام المنزل، وهو التوراة، وما هو منها في شيء، ويقولون: هذا من عند الله أوحاه الله إلى نبيه موسى، وما هو من عند الله، وهم لأجل دنياهم يقولون على الله الكذب، وهم يعلمون أنهم كاذبون."},{"id":"372","jozz":"3","page":"60","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"4","line_end":"7","aya_no":"79","aya_text":"مَا كَانَ لِبَشَرٍ أَن يُؤۡتِيَهُ ٱللَّهُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُواْ عِبَادٗا لِّي مِن دُونِ ٱللَّهِ وَلَٰكِن كُونُواْ رَبَّٰنِيِّـۧنَ بِمَا كُنتُمۡ تُعَلِّمُونَ ٱلۡكِتَٰبَ وَبِمَا كُنتُمۡ تَدۡرُسُونَ","aya_text_emlaey":"ما كان لبشر أن يؤتيه الله الكتاب والحكم والنبوة ثم يقول للناس كونوا عبادا لي من دون الله ولكن كونوا ربانيين بما كنتم تعلمون الكتاب وبما كنتم تدرسون","aya_tafseer":"[79] ما ينبغي لأحد من البشر أن يُنزِّل الله عليه كتابه ويجعله حكماً بين خلقه ويختاره نبيّاً، ثم يقولَ للناس: اعبدوني من دون الله، ولكن يقول: كونوا حكماء فقهاء علماء بما كنتم تُعَلِّمونه غيركم مِن وحي الله تعالى، وبما تدرسونه منه حفظاً وعلماً وفقهاً."},{"id":"373","jozz":"3","page":"60","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"7","line_end":"9","aya_no":"80","aya_text":"وَلَا يَأۡمُرَكُمۡ أَن تَتَّخِذُواْ ٱلۡمَلَٰٓئِكَةَ وَٱلنَّبِيِّـۧنَ أَرۡبَابًاۚ أَيَأۡمُرُكُم بِٱلۡكُفۡرِ بَعۡدَ إِذۡ أَنتُم مُّسۡلِمُونَ","aya_text_emlaey":"ولا يأمركم أن تتخذوا الملائكة والنبيين أربابا أيأمركم بالكفر بعد إذ أنتم مسلمون","aya_tafseer":"[80] وما كان لأحد منهم أن يأمركم باتخاذ الملائكة والنبيين أرباباً تعبدونهم من دون الله. أيُعْقَلُ -أيها الناس- أن يأمركم بالكفر بالله بعد انقيادكم لأمره؟"},{"id":"374","jozz":"3","page":"60","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"9","line_end":"13","aya_no":"81","aya_text":"وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّـۧنَ لَمَآ ءَاتَيۡتُكُم مِّن كِتَٰبٖ وَحِكۡمَةٖ ثُمَّ جَآءَكُمۡ رَسُولٞ مُّصَدِّقٞ لِّمَا مَعَكُمۡ لَتُؤۡمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥۚ قَالَ ءَأَقۡرَرۡتُمۡ وَأَخَذۡتُمۡ عَلَىٰ ذَٰلِكُمۡ إِصۡرِيۖ قَالُوٓاْ أَقۡرَرۡنَاۚ قَالَ فَٱشۡهَدُواْ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّٰهِدِينَ","aya_text_emlaey":"وإذ أخذ الله ميثاق النبيين لما آتيتكم من كتاب وحكمة ثم جاءكم رسول مصدق لما معكم لتؤمنن به ولتنصرنه قال أأقررتم وأخذتم على ذلكم إصري قالوا أقررنا قال فاشهدوا وأنا معكم من الشاهدين","aya_tafseer":"[81] واذكر -أيها الرسول- إذ أخذ الله سبحانه العهد المؤكد على جميع الأنبياء: لَئِنْ آتيتكم من كتاب وحكمة، ثم جاءكم رسول من عندي، مصدق لما معكم لتؤمنن به ولتنصرنَّه. فهل أقررتم واعترفتم بذلك وأخذتم على ذلك عهدي الموثَّق؟ قالوا: أقررنا بذلك، قال: فليشهدْ بعضكم على بعض، واشهدوا على أممكم بذلك، وأنا معكم من الشاهدين عليكم وعليهم. وفي هذا أن الله أخذ الميثاق على كل نبي أن يؤمن بمحمد -صلى الله عليه وسلم-، وأخذ الميثاق على أمم الأنبياء بذلك."},{"id":"375","jozz":"3","page":"60","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"13","line_end":"14","aya_no":"82","aya_text":"فَمَن تَوَلَّىٰ بَعۡدَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ","aya_text_emlaey":"فمن تولى بعد ذلك فأولئك هم الفاسقون","aya_tafseer":"[82] فمن أعرض عن دعوة الإسلام بعد هذا البيان وهذا العهد الذي أخذه الله على أنبيائه، فأولئك هم الخارجون عن دين الله وطاعة ربهم."},{"id":"376","jozz":"3","page":"60","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"14","line_end":"15","aya_no":"83","aya_text":"أَفَغَيۡرَ دِينِ ٱللَّهِ يَبۡغُونَ وَلَهُۥٓ أَسۡلَمَ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا وَإِلَيۡهِ يُرۡجَعُونَ","aya_text_emlaey":"أفغير دين الله يبغون وله أسلم من في السموات والأرض طوعا وكرها وإليه يرجعون","aya_tafseer":"[83] أيريد هؤلاء الفاسقون من أهل الكتاب غير دين الله -وهو الإسلام الذي بعث الله به محمداً -صلى الله عليه وسلم--، مع أن كل مَن في السموات والأرض استسلم وانقاد وخضع لله طواعية -كالمؤمنين- ورغماً عنهم عند الشدائد، حين لا ينفعهم ذلك وهم الكفار، كما خضع له سائر الكائنات، وإليه يُرجَعون يوم المعاد، فيجازي كُلّاً بعمله. وهذا تحذير من الله تعالى لخلقه أن يرجع إليه أحد منهم على غير ملة الإسلام."},{"id":"377","jozz":"3","page":"61","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"4","aya_no":"84","aya_text":"قُلۡ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيۡنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ","aya_text_emlaey":"قل آمنا بالله وما أنـزل علينا وما أنـزل على إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط وما أوتي موسى وعيسى والنبيون من ربهم لا نفرق بين أحد منهم ونحن له مسلمون","aya_tafseer":"[84] قل لهم -أيها الرسول-: صدَّقنا بالله وأطعنا، فلا رب لنا غيره، ولا معبود لنا سواه، وآمنَّا بالوحي الذي أنزله الله علينا، والذي أنزله على إبراهيم خليل الله، وابنيه إسماعيل وإسحاق، وابن ابنه يعقوب بن إسحاق، والذي أنزله على الأسباط -وهم الأنبياء من ولد يعقوب، الذين كانوا في قبائل بني إسرائيل الاثنتي عشرة - وما أوتي موسى وعيسى من التوراة والإنجيل، وما أنزله الله على أنبيائه، نؤمن بذلك كله، ولا نفرق بين أحد منهم، ونحن لله وحده منقادون بالطاعة، مُقِرُّون له بالربوبية والألوهية والعبادة."},{"id":"378","jozz":"3","page":"61","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"4","line_end":"5","aya_no":"85","aya_text":"وَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينٗا فَلَن يُقۡبَلَ مِنۡهُ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ","aya_text_emlaey":"ومن يبتغ غير الإسلام دينا فلن يقبل منه وهو في الآخرة من الخاسرين","aya_tafseer":"[85] ومن يطلب ديناً غير دين الإسلام الذي هو الاستسلام لله بالتوحيد والانقياد له بالطاعة، والعبودية، ولرسوله النبي الخاتم محمد -صلى الله عليه وسلم- بالإيمان به وبمتابعته ومحبته ظاهراً وباطناً، فلن يُقبل منه ذلك، وهو في الآخرة من الخاسرين الذين بخسوا أنفسهم حظوظها."},{"id":"379","jozz":"3","page":"61","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"5","line_end":"8","aya_no":"86","aya_text":"كَيۡفَ يَهۡدِي ٱللَّهُ قَوۡمٗا كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ وَشَهِدُوٓاْ أَنَّ ٱلرَّسُولَ حَقّٞ وَجَآءَهُمُ ٱلۡبَيِّنَٰتُۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ","aya_text_emlaey":"كيف يهدي الله قوما كفروا بعد إيمانهم وشهدوا أن الرسول حق وجاءهم البينات والله لا يهدي القوم الظالمين","aya_tafseer":"[86] كيف يوفق الله للإيمان به وبرسوله قوماً جحدوا نبوة محمد -صلى الله عليه وسلم- بعد إيمانهم به، وشهدوا أن محمداً -صلى الله عليه وسلم- حق وما جاء به هو الحق، وجاءهم الحجج من عند الله والدلائل بصحة ذلك؟ والله لا يوفق للحق والصواب الذين عدلوا عن الحق إلى الباطل، فاختاروا الكفر على الإيمان."},{"id":"380","jozz":"3","page":"61","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"9","aya_no":"87","aya_text":"أُوْلَٰٓئِكَ جَزَآؤُهُمۡ أَنَّ عَلَيۡهِمۡ لَعۡنَةَ ٱللَّهِ وَٱلۡمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجۡمَعِينَ","aya_text_emlaey":"أولئك جزاؤهم أن عليهم لعنة الله والملائكة والناس أجمعين","aya_tafseer":"[87] أولئك الظالمون جزاؤهم أنَّ عليهم لعنة الله والملائكة والناسِ أجمعين، فهم مطرودون من رحمة الله."},{"id":"381","jozz":"3","page":"61","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"9","line_end":"10","aya_no":"88","aya_text":"خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ يُنظَرُونَ","aya_text_emlaey":"خالدين فيها لا يخفف عنهم العذاب ولا هم ينظرون","aya_tafseer":"[88] ماكثين في النار، لا يُرفع عنهم العذاب قليلاً ليستريحوا، ولا يُؤخر عنهم لمعذرة يعتذرون بها."},{"id":"382","jozz":"3","page":"61","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"10","line_end":"11","aya_no":"89","aya_text":"إِلَّا ٱلَّذِينَ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ","aya_text_emlaey":"إلا الذين تابوا من بعد ذلك وأصلحوا فإن الله غفور رحيم","aya_tafseer":"[89] إلا الذين رجعوا إلى ربهم بالتوبة النصوح من بعد كفرهم وظلمهم، وأصلحوا ما أفسدوه بتوبتهم فإن الله يقبلها، فهو غفور لذنوب عباده، رحيم بهم."},{"id":"383","jozz":"3","page":"61","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"11","line_end":"13","aya_no":"90","aya_text":"إِنَّ ٱلَّذِينَ كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّن تُقۡبَلَ تَوۡبَتُهُمۡ وَأُوْلَٰٓئِكَ هُمُ ٱلضَّآلُّونَ","aya_text_emlaey":"إن الذين كفروا بعد إيمانهم ثم ازدادوا كفرا لن تقبل توبتهم وأولئك هم الضالون","aya_tafseer":"[90] إن الذين كفروا بعد إيمانهم واستمروا على الكفر إلى الممات لن تُقبل لهم توبة عند حضور الموت، وأولئك هم الذين ضلُّوا السبيل، فأخطَؤُوا منهجه."},{"id":"384","jozz":"3","page":"61","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"13","line_end":"15","aya_no":"91","aya_text":"إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ كُفَّارٞ فَلَن يُقۡبَلَ مِنۡ أَحَدِهِم مِّلۡءُ ٱلۡأَرۡضِ ذَهَبٗا وَلَوِ ٱفۡتَدَىٰ بِهِۦٓۗ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ وَمَا لَهُم مِّن نَّٰصِرِينَ","aya_text_emlaey":"إن الذين كفروا وماتوا وهم كفار فلن يقبل من أحدهم ملء الأرض ذهبا ولو افتدى به أولئك لهم عذاب أليم وما لهم من ناصرين","aya_tafseer":"[91] إن الذين جحدوا نبوة محمد -صلى الله عليه وسلم-، وماتوا على الكفر بالله ورسوله، فلن يُقبل من أحدهم يوم القيامة ملء الأرض ذهباً؛ ليفتدي به نفسه من عذاب الله، ولو افتدى به نفسه فِعْلاً. أولئك لهم عذاب موجع، وما لهم مِن أحد ينقذهم من عذاب الله."},{"id":"385","jozz":"4","page":"62","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"2","aya_no":"92","aya_text":"لَن تَنَالُواْ ٱلۡبِرَّ حَتَّىٰ تُنفِقُواْ مِمَّا تُحِبُّونَۚ وَمَا تُنفِقُواْ مِن شَيۡءٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ","aya_text_emlaey":"لن تنالوا البر حتى تنفقوا مما تحبون وما تنفقوا من شيء فإن الله به عليم","aya_tafseer":"[92] لن تدركوا الجنة حتى تتصدقوا مما تحبون، وأي شيء تتصدقوا به مهما كان قليلاً أو كثيراً فإن الله به عليم، وسيجازي كلَّ منفق بحسب عمله."},{"id":"386","jozz":"4","page":"62","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"2","line_end":"4","aya_no":"93","aya_text":"۞ كُلُّ ٱلطَّعَامِ كَانَ حِلّٗا لِّبَنِيٓ إِسۡرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسۡرَٰٓءِيلُ عَلَىٰ نَفۡسِهِۦ مِن قَبۡلِ أَن تُنَزَّلَ ٱلتَّوۡرَىٰةُۚ قُلۡ فَأۡتُواْ بِٱلتَّوۡرَىٰةِ فَٱتۡلُوهَآ إِن كُنتُمۡ صَٰدِقِينَ","aya_text_emlaey":"كل الطعام كان حلا لبني إسرائيل إلا ما حرم إسرائيل على نفسه من قبل أن تنـزل التوراة قل فأتوا بالتوراة فاتلوها إن كنتم صادقين","aya_tafseer":"[93] كل الأطعمة الطيِّبة كانت حلالاً لأبناء يعقوب عليه السلام إلَّا ما حرَّم يعقوب على نفسه لمرض نزل به، وذلك مِن قبل أن تُنَزَّل التوراة. فلما نُزِّلت التوراة حَرَّم الله على بني إسرائيل بعض الأطعمة التي كانت حلالاً لهم؛ وذلك لظلمهم وبغيهم. قل لهم -أيها الرسول-: هاتوا التوراة، واقرؤوا ما فيها إن كنتم محقين في دعواكم أن الله أنزل فيها تحريم ما حرَّمه يعقوب على نفسه، حتى تعلموا صدق ما جاء في القرآن مِن أنَّ الله لم يحرم على بني إسرائيل شيئاً من قَبْل نزول التوراة، إلا ما حرَّمه يعقوب على نفسه."},{"id":"387","jozz":"4","page":"62","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"5","line_end":"6","aya_no":"94","aya_text":"فَمَنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ ٱلۡكَذِبَ مِنۢ بَعۡدِ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ","aya_text_emlaey":"فمن افترى على الله الكذب من بعد ذلك فأولئك هم الظالمون","aya_tafseer":"[94] فمَن كذب على الله من بعد قراءة التوراة ووضوح الحقيقة، فأولئك هم الظالمون القائلون على الله بالباطل."},{"id":"388","jozz":"4","page":"62","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"6","line_end":"7","aya_no":"95","aya_text":"قُلۡ صَدَقَ ٱللَّهُۗ فَٱتَّبِعُواْ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ","aya_text_emlaey":"قل صدق الله فاتبعوا ملة إبراهيم حنيفا وما كان من المشركين","aya_tafseer":"[95] قل لهم -أيها الرسول- صَدَق الله فيما أخبر به وفيما شرعه. فإن كنتم صادقين في محبتكم وانتسابكم لخليل الله إبراهيم عليه السلام، فاتبعوا ملَّته التي شرعها الله على لسان محمد -صلى الله عليه وسلم-، فإنها الحق الذي لا شك فيه. وما كان إبراهيم عليه السلام من المشركين بالله في توحيده وعبادته أحداً."},{"id":"389","jozz":"4","page":"62","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"7","line_end":"8","aya_no":"96","aya_text":"إِنَّ أَوَّلَ بَيۡتٖ وُضِعَ لِلنَّاسِ لَلَّذِي بِبَكَّةَ مُبَارَكٗا وَهُدٗى لِّلۡعَٰلَمِينَ","aya_text_emlaey":"إن أول بيت وضع للناس للذي ببكة مباركا وهدى للعالمين","aya_tafseer":"[96] إن أول بيت بُني لعبادة الله في الأرض لهو بيت الله الحرام الذي في «مكة»، وهذا البيت مبارك تضاعف فيه الحسنات، وتتنزل فيه الرحمات، وفي استقباله في الصلاة، وقصدِه لأداء الحج والعمرة، صلاح وهداية للناس أجمعين."},{"id":"390","jozz":"4","page":"62","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"10","aya_no":"97","aya_text":"فِيهِ ءَايَٰتُۢ بَيِّنَٰتٞ مَّقَامُ إِبۡرَٰهِيمَۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنٗاۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلۡبَيۡتِ مَنِ ٱسۡتَطَاعَ إِلَيۡهِ سَبِيلٗاۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنِ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"فيه آيات بينات مقام إبراهيم ومن دخله كان آمنا ولله على الناس حج البيت من استطاع إليه سبيلا ومن كفر فإن الله غني عن العالمين","aya_tafseer":"[97] في هذا البيت دلالات ظاهرات أنه من بناء إبراهيم، وأن الله عظَّمه وشرَّفه، منها: مقام إبراهيم عليه السلام، وهو الحَجَر الذي كان يقف عليه حين كان يرفع القواعد من البيت هو وابنه إسماعيل، ومن دخل هذا البيت أَمِنَ على نفسه فلا يناله أحد بسوء. وقد أوجب الله على المستطيع من الناس في أي مكان قَصْدَ هذا البيت لأداء مناسك الحج. ومن جحد فريضة الحج فقد كفر، والله غني عنه وعن حجِّه وعمله، وعن سائر خَلْقه."},{"id":"391","jozz":"4","page":"62","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"11","line_end":"12","aya_no":"98","aya_text":"قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعۡمَلُونَ","aya_text_emlaey":"قل ياأهل الكتاب لم تكفرون بآيات الله والله شهيد على ما تعملون","aya_tafseer":"[98] قل -أيها الرسول- لأهل الكتاب من اليهود والنصارى: لِمَ تجحدون حجج الله التي دلَّتْ على أن دين الله هو الإسلام، وتنكرون ما في كتبكم من دلائل وبراهين على ذلك، وأنتم تعلمون ؟ والله شهيد على صنيعكم. وفي ذلك تهديد ووعيد لهم."},{"id":"392","jozz":"4","page":"62","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"14","aya_no":"99","aya_text":"قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ تَبۡغُونَهَا عِوَجٗا وَأَنتُمۡ شُهَدَآءُۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ","aya_text_emlaey":"قل ياأهل الكتاب لم تصدون عن سبيل الله من آمن تبغونها عوجا وأنتم شهداء وما الله بغافل عما تعملون","aya_tafseer":"[99] قل -أيها الرسول- لليهود والنصارى: لِمَ تمنعون من الإسلام من يريد الدخول فيه تطلبون له زيغاً وميلاً عن القصد والاستقامة، وأنتم تعلمون أن ما جئتُ به هو الحق؟ وما الله بغافل عما تعملون، وسوف يجازيكم على ذلك."},{"id":"393","jozz":"4","page":"62","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"14","line_end":"15","aya_no":"100","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ فَرِيقٗا مِّنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ يَرُدُّوكُم بَعۡدَ إِيمَٰنِكُمۡ كَٰفِرِينَ","aya_text_emlaey":"ياأيها الذين آمنوا إن تطيعوا فريقا من الذين أوتوا الكتاب يردوكم بعد إيمانكم كافرين","aya_tafseer":"[100] يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إن تطيعوا جماعة من اليهود والنصارى ممن آتاهم الله التوراة والإنجيل، يضلوكم، ويلقوا إليكم الشُّبَه في دينكم؛ لترجعوا جاحدين للحق بعد أن كنتم مؤمنين به، فلا تأمنوهم على دينكم، ولا تقبلوا لهم رأياً أو مشورة."},{"id":"394","jozz":"4","page":"63","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"2","aya_no":"101","aya_text":"وَكَيۡفَ تَكۡفُرُونَ وَأَنتُمۡ تُتۡلَىٰ عَلَيۡكُمۡ ءَايَٰتُ ٱللَّهِ وَفِيكُمۡ رَسُولُهُۥۗ وَمَن يَعۡتَصِم بِٱللَّهِ فَقَدۡ هُدِيَ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ","aya_text_emlaey":"وكيف تكفرون وأنتم تتلى عليكم آيات الله وفيكم رسوله ومن يعتصم بالله فقد هدي إلى صراط مستقيم","aya_tafseer":"[101] وكيف تكفرون بالله -أيها المؤمنون- وآيات القرآن تتلى عليكم، وفيكم رسول الله محمد -صلى الله عليه وسلم- يبلغها لكم؟ ومَن يتوكل على الله ويستمسك بالقرآن والسنة فقد وُفِّق لطريق واضح، ومنهاج مستقيم."},{"id":"395","jozz":"4","page":"63","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"3","line_end":"4","aya_no":"102","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ","aya_text_emlaey":"ياأيها الذين آمنوا اتقوا الله حق تقاته ولا تموتن إلا وأنتم مسلمون","aya_tafseer":"[102] يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، خافوا الله حق خوفه: وذلك بأن يطاع فلا يُعصى، ويُشكَر فلا يكفر، ويُذكَر فلا ينسى، وداوموا على تمسككم بإسلامكم إلى آخر حياتكم؛ لتلقوا الله وأنتم عليه."},{"id":"396","jozz":"4","page":"63","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"4","line_end":"8","aya_no":"103","aya_text":"وَٱعۡتَصِمُواْ بِحَبۡلِ ٱللَّهِ جَمِيعٗا وَلَا تَفَرَّقُواْۚ وَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ كُنتُمۡ أَعۡدَآءٗ فَأَلَّفَ بَيۡنَ قُلُوبِكُمۡ فَأَصۡبَحۡتُم بِنِعۡمَتِهِۦٓ إِخۡوَٰنٗا وَكُنتُمۡ عَلَىٰ شَفَا حُفۡرَةٖ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنۡهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَهۡتَدُونَ","aya_text_emlaey":"واعتصموا بحبل الله جميعا ولا تفرقوا واذكروا نعمة الله عليكم إذ كنتم أعداء فألف بين قلوبكم فأصبحتم بنعمته إخوانا وكنتم على شفا حفرة من النار فأنقذكم منها كذلك يبين الله لكم آياته لعلكم تهتدون","aya_tafseer":"[103] وتمسَّكوا جميعاً بكتاب ربكم وهدي نبيكم، ولا تفعلوا ما يؤدي إلى فرقتكم. واذكروا نعمة جليلة أنعم الله بها عليكم: إذ كنتم -أيها المؤمنون- قبل الإسلام أعداء، فجمع الله قلوبكم على محبته ومحبة رسوله، وألقى في قلوبكم محبة بعضكم لبعض، فأصبحتم بفضله إخواناً متحابّين، وكنتم على حافَة نار جهنم، فهداكم الله بالإسلام ونجَّاكم من النار. وكما بَيَّن الله لكم معالم الإيمان الصحيح فكذلك يبيِّن لكم كل ما فيه صلاحكم؛ لتهتدوا إلى سبيل الرشاد، وتسلكوها، فلا تضلوا عنها."},{"id":"397","jozz":"4","page":"63","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"9","aya_no":"104","aya_text":"وَلۡتَكُن مِّنكُمۡ أُمَّةٞ يَدۡعُونَ إِلَى ٱلۡخَيۡرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","aya_text_emlaey":"ولتكن منكم أمة يدعون إلى الخير ويأمرون بالمعروف وينهون عن المنكر وأولئك هم المفلحون","aya_tafseer":"[104] ولتكن منكم -أيها المؤمنون- جماعة تدعو إلى الخير وتأمر بالمعروف، وهو ما عُرف حسنه شرعاً وعقلاً، وتنهى عن المنكر، وهو ما عُرف قبحه شرعاً وعقلاً، وأولئك هم الفائزون بجنات النعيم."},{"id":"398","jozz":"4","page":"63","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"10","line_end":"11","aya_no":"105","aya_text":"وَلَا تَكُونُواْ كَٱلَّذِينَ تَفَرَّقُواْ وَٱخۡتَلَفُواْ مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡبَيِّنَٰتُۚ وَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ عَظِيمٞ","aya_text_emlaey":"ولا تكونوا كالذين تفرقوا واختلفوا من بعد ما جاءهم البينات وأولئك لهم عذاب عظيم","aya_tafseer":"[105] ولا تكونوا -أيها المؤمنون- كأهل الكتاب الذين وقعت بينهم العداوة والبغضاء فتفرَّقوا شيعاً وأحزاباً، واختلفوا في أصول دينهم من بعد أن اتضح لهم الحق، وأولئك مستحقون لعذابٍ عظيم موجع."},{"id":"399","jozz":"4","page":"63","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"11","line_end":"13","aya_no":"106","aya_text":"يَوۡمَ تَبۡيَضُّ وُجُوهٞ وَتَسۡوَدُّ وُجُوهٞۚ فَأَمَّا ٱلَّذِينَ ٱسۡوَدَّتۡ وُجُوهُهُمۡ أَكَفَرۡتُم بَعۡدَ إِيمَٰنِكُمۡ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ","aya_text_emlaey":"يوم تبيض وجوه وتسود وجوه فأما الذين اسودت وجوههم أكفرتم بعد إيمانكم فذوقوا العذاب بما كنتم تكفرون","aya_tafseer":"[106] يوم القيامة تَبيَضُّ وجوه أهل السعادة الذين آمنوا بالله ورسوله، وامتثلوا أمره، وتَسْوَدُّ وجوه أهل الشقاوة ممن كذبوا رسوله، وعصوا أمره. فأما الذين اسودَّت وجوههم، فيقال لهم توبيخاً: أكفرتم بعد إيمانكم، فاخترتم الكفر على الإيمان؟ فذوقوا العذاب بسبب كفركم."},{"id":"400","jozz":"4","page":"63","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"13","line_end":"14","aya_no":"107","aya_text":"وَأَمَّا ٱلَّذِينَ ٱبۡيَضَّتۡ وُجُوهُهُمۡ فَفِي رَحۡمَةِ ٱللَّهِۖ هُمۡ فِيهَا خَٰلِدُونَ","aya_text_emlaey":"وأما الذين ابيضت وجوههم ففي رحمة الله هم فيها خالدون","aya_tafseer":"[107] وأما الذين ابيضَّتْ وجوههم بنضرة النعيم، وما بُشِّروا به من الخير، فهم في جنة الله ونعيمها، وهم باقون فيها، لا يخرجون منها أبداً."},{"id":"401","jozz":"4","page":"63","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"14","line_end":"15","aya_no":"108","aya_text":"تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۗ وَمَا ٱللَّهُ يُرِيدُ ظُلۡمٗا لِّلۡعَٰلَمِينَ","aya_text_emlaey":"تلك آيات الله نتلوها عليك بالحق وما الله يريد ظلما للعالمين","aya_tafseer":"[108] هذه آيات الله وبراهينه الساطعة، نتلوها ونقصُّها عليك -أيها الرسول- بالصدق واليقين. وما الله بظالم أحداً من خلقه، ولا بمنقص شيئاً من أعمالهم؛ لأنه الحاكم العدل الذي لا يجور."},{"id":"402","jozz":"4","page":"64","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"1","aya_no":"109","aya_text":"وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ","aya_text_emlaey":"ولله ما في السموات وما في الأرض وإلى الله ترجع الأمور","aya_tafseer":"[109] ولله ما في السموات وما في الأرض، مُلْكٌ له وحده خلقاً وتدبيراً، ومصير جميع الخلائق إليه وحده، فيجازي كُلّاً على قَدْر استحقاقه."},{"id":"403","jozz":"4","page":"64","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"2","line_end":"5","aya_no":"110","aya_text":"كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَتَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَتُؤۡمِنُونَ بِٱللَّهِۗ وَلَوۡ ءَامَنَ أَهۡلُ ٱلۡكِتَٰبِ لَكَانَ خَيۡرٗا لَّهُمۚ مِّنۡهُمُ ٱلۡمُؤۡمِنُونَ وَأَكۡثَرُهُمُ ٱلۡفَٰسِقُونَ","aya_text_emlaey":"كنتم خير أمة أخرجت للناس تأمرون بالمعروف وتنهون عن المنكر وتؤمنون بالله ولو آمن أهل الكتاب لكان خيرا لهم منهم المؤمنون وأكثرهم الفاسقون","aya_tafseer":"[110] أنتم -يا أمة محمد صلى الله عليه وسلم- خير الأُمم وأنفع الناس للناس، تأمرون بالمعروف، وهو ما عُرف حسنه شرعاً وعقلاً، وتنهون عن المنكر، وهو ما عُرف قبحه شرعاً وعقلاً، وتصدقون بالله تصديقاً جازماً يؤيده العمل. ولو آمن أهل الكتاب من اليهود والنصارى بمحمد -صلى الله عليه وسلم- وما جاءهم به من عند الله كما آمنتم، لكان خيراً لهم في الدنيا والآخرة، منهم المؤمنون المصدقون برسالة محمد -صلى الله عليه وسلم- العاملون بها، وهم قليل، وأكثرهم الخارجون عن دين الله وطاعته."},{"id":"404","jozz":"4","page":"64","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"5","line_end":"6","aya_no":"111","aya_text":"لَن يَضُرُّوكُمۡ إِلَّآ أَذٗىۖ وَإِن يُقَٰتِلُوكُمۡ يُوَلُّوكُمُ ٱلۡأَدۡبَارَ ثُمَّ لَا يُنصَرُونَ","aya_text_emlaey":"لن يضروكم إلا أذى وإن يقاتلوكم يولوكم الأدبار ثم لا ينصرون","aya_tafseer":"[111] لن يضركم هؤلاء الفاسقون من أهل الكتاب إلا ما يؤذي أسماعكم من ألفاظ الشرك والكفر وغير ذلك، وإن يقاتلوكم يُهْزَموا، ويهربوا مولِّين الأدبار، ثم لا يُنْصَرون عليكم بأي حال."},{"id":"405","jozz":"4","page":"64","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"6","line_end":"10","aya_no":"112","aya_text":"ضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ أَيۡنَ مَا ثُقِفُوٓاْ إِلَّا بِحَبۡلٖ مِّنَ ٱللَّهِ وَحَبۡلٖ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٖ مِّنَ ٱللَّهِ وَضُرِبَتۡ عَلَيۡهِمُ ٱلۡمَسۡكَنَةُۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ","aya_text_emlaey":"ضربت عليهم الذلة أين ما ثقفوا إلا بحبل من الله وحبل من الناس وباءوا بغضب من الله وضربت عليهم المسكنة ذلك بأنهم كانوا يكفرون بآيات الله ويقتلون الأنبياء بغير حق ذلك بما عصوا وكانوا يعتدون","aya_tafseer":"[112] جعل الله الهوان والذُّلَّ أمراً لازماً لا يفارق اليهود، فهم أذلاء محتقرون أينما وُجِدوا، إلَّا بعهد من الله وعهد من الناس يأمنون به على أنفسهم وأموالهم، وذلك هو عقد الذمة لهم وإلزامهم أحكام الإسلام، ورجعوا بغضب من الله مستحقين له، وضُربت عليهم الذلَّة والمسكنة، فلا ترى اليهوديَّ إلا وعليه الخوف والرعب من أهل الإيمان؛ ذلك الذي جعله الله عليهم بسبب كفرهم بالله، وتجاوزهم حدوده، وقَتْلهم الأنبياء ظلماً واعتداء، وما جرَّأهم على هذا إلا ارتكابهم للمعاصي، وتجاوزهم حدود الله."},{"id":"406","jozz":"4","page":"64","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"10","line_end":"12","aya_no":"113","aya_text":"۞ لَيۡسُواْ سَوَآءٗۗ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ أُمَّةٞ قَآئِمَةٞ يَتۡلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيۡلِ وَهُمۡ يَسۡجُدُونَ","aya_text_emlaey":"ليسوا سواء من أهل الكتاب أمة قائمة يتلون آيات الله آناء الليل وهم يسجدون","aya_tafseer":"[113] ليس أهل الكتاب متساوين: فمنهم جماعة مستقيمة على أمر الله مؤمنة برسوله محمد -صلى الله عليه وسلم-، يقومون الليل مرتلين آيات القرآن الكريم، مقبلين على مناجاة الله في صلواتهم."},{"id":"407","jozz":"4","page":"64","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"14","aya_no":"114","aya_text":"يُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِۖ وَأُوْلَٰٓئِكَ مِنَ ٱلصَّٰلِحِينَ","aya_text_emlaey":"يؤمنون بالله واليوم الآخر ويأمرون بالمعروف وينهون عن المنكر ويسارعون في الخيرات وأولئك من الصالحين","aya_tafseer":"[114] يؤمنون بالله واليوم الآخر، ويأمرون بالخير كله، وينهون عن الشر كلِّه، ويبادرون إلى فعل الخيرات، وأولئك مِن عباد الله الصالحين."},{"id":"408","jozz":"4","page":"64","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"14","line_end":"15","aya_no":"115","aya_text":"وَمَا يَفۡعَلُواْ مِنۡ خَيۡرٖ فَلَن يُكۡفَرُوهُۗ وَٱللَّهُ عَلِيمُۢ بِٱلۡمُتَّقِينَ","aya_text_emlaey":"وما يفعلوا من خير فلن يكفروه والله عليم بالمتقين","aya_tafseer":"[115] وأيُّ عمل قَلَّ أو كَثُر من أعمال الخير تعمله هذه الطائفة المؤمنة فلن يضيع عند الله، بل يُشكر لهم، ويجازون عليه. والله عليم بالمتقين الذين فعلوا الخيرات وابتعدوا عن المحرمات؛ ابتغاء رضوان الله، وطلباً لثوابه."},{"id":"409","jozz":"4","page":"65","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"2","aya_no":"116","aya_text":"إِنَّ ٱلَّذِينَ كَفَرُواْ لَن تُغۡنِيَ عَنۡهُمۡ أَمۡوَٰلُهُمۡ وَلَآ أَوۡلَٰدُهُم مِّنَ ٱللَّهِ شَيۡـٔٗاۖ وَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ","aya_text_emlaey":"إن الذين كفروا لن تغني عنهم أموالهم ولا أولادهم من الله شيئا وأولئك أصحاب النار هم فيها خالدون","aya_tafseer":"[116] إن الذين كفروا بآيات الله، وكذبوا رسله، لن تدفع عنهم أموالهم ولا أولادهم شيئاً من عذاب الله في الدنيا ولا في الآخرة، وأولئك أصحاب النار الملازمون لها، لا يخرجون منها."},{"id":"410","jozz":"4","page":"65","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"3","line_end":"5","aya_no":"117","aya_text":"مَثَلُ مَا يُنفِقُونَ فِي هَٰذِهِ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَثَلِ رِيحٖ فِيهَا صِرٌّ أَصَابَتۡ حَرۡثَ قَوۡمٖ ظَلَمُوٓاْ أَنفُسَهُمۡ فَأَهۡلَكَتۡهُۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِنۡ أَنفُسَهُمۡ يَظۡلِمُونَ","aya_text_emlaey":"مثل ما ينفقون في هذه الحياة الدنيا كمثل ريح فيها صر أصابت حرث قوم ظلموا أنفسهم فأهلكته وما ظلمهم الله ولكن أنفسهم يظلمون","aya_tafseer":"[117] مَثَلُ ما ينفق الكافرون في وجوه الخير في هذه الحياة الدنيا وما يؤملونه من ثواب، كمثل ريح فيها بَرْد شديد هَبَّتْ على زرع قوم كانوا يرجون خيره، وبسبب ذنوبهم لم تُبْقِ الريح منه شيئاً. وهؤلاء الكافرون لا يجدون في الآخرة ثواباً، وما ظلمهم الله بذلك، ولكنهم ظلموا أنفسهم بكفرهم وعصيانهم."},{"id":"411","jozz":"4","page":"65","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"5","line_end":"8","aya_no":"118","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ بِطَانَةٗ مِّن دُونِكُمۡ لَا يَأۡلُونَكُمۡ خَبَالٗا وَدُّواْ مَا عَنِتُّمۡ قَدۡ بَدَتِ ٱلۡبَغۡضَآءُ مِنۡ أَفۡوَٰهِهِمۡ وَمَا تُخۡفِي صُدُورُهُمۡ أَكۡبَرُۚ قَدۡ بَيَّنَّا لَكُمُ ٱلۡأٓيَٰتِۖ إِن كُنتُمۡ تَعۡقِلُونَ","aya_text_emlaey":"ياأيها الذين آمنوا لا تتخذوا بطانة من دونكم لا يألونكم خبالا ودوا ما عنتم قد بدت البغضاء من أفواههم وما تخفي صدورهم أكبر قد بينا لكم الآيات إن كنتم تعقلون","aya_tafseer":"[118] يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه لا تتخذوا الكافرين أولياء من دون المؤمنين، تُطْلعونهم على أسراركم، فهؤلاء لا يَفْتُرون عن إفساد حالكم، وهم يفرحون بما يصيبكم من ضرر ومكروه، وقد ظهرت شدة البغض في كلامهم، وما تخفي صدورهم من العداوة لكم أكبر وأعظم. قد بيَّنَّا لكم البراهين والحجج؛ لتتعظوا وتحذروا، إن كنتم تعقلون عن الله مواعظه وأمره ونهيه."},{"id":"412","jozz":"4","page":"65","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"9","line_end":"12","aya_no":"119","aya_text":"هَٰٓأَنتُمۡ أُوْلَآءِ تُحِبُّونَهُمۡ وَلَا يُحِبُّونَكُمۡ وَتُؤۡمِنُونَ بِٱلۡكِتَٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمۡ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ عَضُّواْ عَلَيۡكُمُ ٱلۡأَنَامِلَ مِنَ ٱلۡغَيۡظِۚ قُلۡ مُوتُواْ بِغَيۡظِكُمۡۗ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ","aya_text_emlaey":"ها أنتم أولاء تحبونهم ولا يحبونكم وتؤمنون بالكتاب كله وإذا لقوكم قالوا آمنا وإذا خلوا عضوا عليكم الأنامل من الغيظ قل موتوا بغيظكم إن الله عليم بذات الصدور","aya_tafseer":"[119] ها هو ذا الدليل على خطئكم في محبتهم، فأنتم تحبونهم وتحسنون إليهم، وهم لا يحبونكم ويحملون لكم العداوة والبغضاء، وأنتم تؤمنون بالكتب المنزلة كلها ومنها كتابهم، وهم لا يؤمنون بكتابكم، فكيف تحبونهم؟ وإذا لقوكم قالوا -نفاقاً-: آمنَّا وصدَّقْنا، وإذا خلا بعضهم إلى بعض بدا عليهم الغمُّ والحزن، فعَضُّوا أطراف أصابعهم من شدة الغضب؛ لما يرون من ألفة المسلمين واجتماع كلمتهم، وإعزاز الإسلام، وإذلالهم به. قل لهم -أيها الرسول-: موتوا بشدة غضبكم. إن الله مُطَّلِع على ما تخفي الصدور، وسيجازي كُلّاً على ما قَدَّم مِن خير أو شر."},{"id":"413","jozz":"4","page":"65","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"14","aya_no":"120","aya_text":"إِن تَمۡسَسۡكُمۡ حَسَنَةٞ تَسُؤۡهُمۡ وَإِن تُصِبۡكُمۡ سَيِّئَةٞ يَفۡرَحُواْ بِهَاۖ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ لَا يَضُرُّكُمۡ كَيۡدُهُمۡ شَيۡـًٔاۗ إِنَّ ٱللَّهَ بِمَا يَعۡمَلُونَ مُحِيطٞ","aya_text_emlaey":"إن تمسسكم حسنة تسؤهم وإن تصبكم سيئة يفرحوا بها وإن تصبروا وتتقوا لا يضركم كيدهم شيئا إن الله بما يعملون محيط","aya_tafseer":"[120] ومن عداوة هؤلاء أنكم -أيها المؤمنون- إن نزل بكم أمرٌ حسن مِن نصر وغنيمة ظهرت عليهم الكآبة والحزن، وإن وقع بكم مكروه من هزيمة أو نقص في الأموال والأنفس والثمرات فرحوا بذلك، وإن تصبروا على ما أصابكم، وتتقوا الله فيما أمركم به ونهاكم عنه، لا يضركم أذى مكرهم. والله بجميع ما يعمل هؤلاء الكفار من الفساد محيط، وسيجازيهم على ذلك."},{"id":"414","jozz":"4","page":"65","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"14","line_end":"15","aya_no":"121","aya_text":"وَإِذۡ غَدَوۡتَ مِنۡ أَهۡلِكَ تُبَوِّئُ ٱلۡمُؤۡمِنِينَ مَقَٰعِدَ لِلۡقِتَالِۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ","aya_text_emlaey":"وإذ غدوت من أهلك تبوئ المؤمنين مقاعد للقتال والله سميع عليم","aya_tafseer":"[121] واذكر -أيها الرسول- حين خَرَجْتَ من بيتك لابساً عُدَّة الحرب، تنظم صفوف أصحابك، وتُنْزِل كل واحد في منزله للقاء المشركين في غزوة «أُحُد». والله سميع لأقوالكم، عليم بأفعالكم."},{"id":"415","jozz":"4","page":"66","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"2","aya_no":"122","aya_text":"إِذۡ هَمَّت طَّآئِفَتَانِ مِنكُمۡ أَن تَفۡشَلَا وَٱللَّهُ وَلِيُّهُمَاۗ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ","aya_text_emlaey":"إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون","aya_tafseer":"[122] اذكر -أيها النبي- ما كان من أمر بني سَلِمة وبني حارثة حين حدثتهم أنفسهم بالرجوع مع زعيمهم المنافق عبدالله بن أُبَيٍّ؛ خوفاً من لقاء العدو، ولكن الله عصمهم وحفظهم، فساروا معك متوكلين على الله. وعلى الله وحده فليتوكل المؤمنون."},{"id":"416","jozz":"4","page":"66","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"2","line_end":"3","aya_no":"123","aya_text":"وَلَقَدۡ نَصَرَكُمُ ٱللَّهُ بِبَدۡرٖ وَأَنتُمۡ أَذِلَّةٞۖ فَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تَشۡكُرُونَ","aya_text_emlaey":"ولقد نصركم الله ببدر وأنتم أذلة فاتقوا الله لعلكم تشكرون","aya_tafseer":"[123] ولقد نصركم الله -أيها المؤمنون- ﺑ«بدْر» على أعدائكم المشركين مع قلة عَدَدكم وعُدَدكم، فخافوا الله بفعل أوامره واجتناب نواهيه؛ لعلكم تشكرون له نعمه."},{"id":"417","jozz":"4","page":"66","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"3","line_end":"5","aya_no":"124","aya_text":"إِذۡ تَقُولُ لِلۡمُؤۡمِنِينَ أَلَن يَكۡفِيَكُمۡ أَن يُمِدَّكُمۡ رَبُّكُم بِثَلَٰثَةِ ءَالَٰفٖ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُنزَلِينَ","aya_text_emlaey":"إذ تقول للمؤمنين ألن يكفيكم أن يمدكم ربكم بثلاثة آلاف من الملائكة منـزلين","aya_tafseer":"[124] اذكر -أيها النبي- ما كان من أمر أصحابك في «بدر» حين شقَّ عليهم أن يأتي مَدَد للمشركين، فأوحينا إليك أن تقول لهم: ألن تكفيكم معونة ربكم بأن يمدكم بثلاثة آلاف من الملائكة مُنْزَلين من السماء إلى أرض المعركة، يثبتونكم، ويقاتلون معكم؟"},{"id":"418","jozz":"4","page":"66","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"5","line_end":"6","aya_no":"125","aya_text":"بَلَىٰٓۚ إِن تَصۡبِرُواْ وَتَتَّقُواْ وَيَأۡتُوكُم مِّن فَوۡرِهِمۡ هَٰذَا يُمۡدِدۡكُمۡ رَبُّكُم بِخَمۡسَةِ ءَالَٰفٖ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُسَوِّمِينَ","aya_text_emlaey":"بلى إن تصبروا وتتقوا ويأتوكم من فورهم هذا يمددكم ربكم بخمسة آلاف من الملائكة مسومين","aya_tafseer":"[125] بلى يكفيكم هذا المَدَد. وبشارة أخرى لكم: إن تصبروا على لقاء العدو وتتقوا الله بفِعْل ما أمركم به واجتناب ما نهاكم عنه، ويأت كفار «مكة» على الفور مسرعين لقتالكم، يظنون أنهم يستأصلونكم، فإن الله يمدكم بخمسة آلاف من الملائكة مسوِّمين أي: قد أعلموا أنفسهم وخيولهم بعلامات واضحات."},{"id":"419","jozz":"4","page":"66","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"7","line_end":"8","aya_no":"126","aya_text":"وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ لَكُمۡ وَلِتَطۡمَئِنَّ قُلُوبُكُم بِهِۦۗ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ","aya_text_emlaey":"وما جعله الله إلا بشرى لكم ولتطمئن قلوبكم به وما النصر إلا من عند الله العزيز الحكيم","aya_tafseer":"[126] وما جعل الله هذا الإمداد بالملائكة إلا بشرى لكم يبشركم بها ولتطمئن قلوبكم، وتطيب بوعد الله لكم. وما النصر إلا من عند الله العزيز الذي لا يغالَب، الحكيم في تدبيره وفعله."},{"id":"420","jozz":"4","page":"66","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"9","aya_no":"127","aya_text":"لِيَقۡطَعَ طَرَفٗا مِّنَ ٱلَّذِينَ كَفَرُوٓاْ أَوۡ يَكۡبِتَهُمۡ فَيَنقَلِبُواْ خَآئِبِينَ","aya_text_emlaey":"ليقطع طرفا من الذين كفروا أو يكبتهم فينقلبوا خائبين","aya_tafseer":"[127] وكان نصر الله لكم ﺑ«بدْر» ليهلك فريقاً من الكفار بالقتل، ومن نجا منهم من القتل رجع حزيناً قد ضاقت عليه نفسه، يَظْهر عليه الخزي والعار."},{"id":"421","jozz":"4","page":"66","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"10","line_end":"11","aya_no":"128","aya_text":"لَيۡسَ لَكَ مِنَ ٱلۡأَمۡرِ شَيۡءٌ أَوۡ يَتُوبَ عَلَيۡهِمۡ أَوۡ يُعَذِّبَهُمۡ فَإِنَّهُمۡ ظَٰلِمُونَ","aya_text_emlaey":"ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون","aya_tafseer":"[128] ليس لك -أيها الرسول- من أمر العباد شيء، بل الأمر كله لله تعالى وحده لا شريك له، ولعل بعض هؤلاء الذين قاتلوك تنشرح صدورهم للإسلام فيسلموا، فيتوب الله عليهم. ومن بقي على كفره يعذبه الله في الدنيا والآخرة؛ بسبب ظلمه وبغيه."},{"id":"422","jozz":"4","page":"66","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"11","line_end":"12","aya_no":"129","aya_text":"وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ","aya_text_emlaey":"ولله ما في السموات وما في الأرض يغفر لمن يشاء ويعذب من يشاء والله غفور رحيم","aya_tafseer":"[129] ولله وحده ما في السموات وما في الأرض، يغفر لمن يشاء من عباده برحمته، ويعذب من يشاء بعدله. والله غفور لذنوب عباده، رحيم بهم."},{"id":"423","jozz":"4","page":"66","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"14","aya_no":"130","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُواْ ٱلرِّبَوٰٓاْ أَضۡعَٰفٗا مُّضَٰعَفَةٗۖ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ","aya_text_emlaey":"ياأيها الذين آمنوا لا تأكلوا الربا أضعافا مضاعفة واتقوا الله لعلكم تفلحون","aya_tafseer":"[130] يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه احذروا الربا بجميع أنواعه، ولا تأخذوا في القرض زيادة على رؤوس أموالكم وإن قلَّت، فكيف إذا كانت هذه الزيادة تتضاعف كلَّما حان موعد سداد الدين؟ واتقوا الله بالتزام شرعه؛ لتفوزوا في الدنيا والآخرة."},{"id":"424","jozz":"4","page":"66","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"14","line_end":"15","aya_no":"131","aya_text":"وَٱتَّقُواْ ٱلنَّارَ ٱلَّتِيٓ أُعِدَّتۡ لِلۡكَٰفِرِينَ","aya_text_emlaey":"واتقوا النار التي أعدت للكافرين","aya_tafseer":"[131] واجعلوا لأنفسكم وقاية بينكم وبين النار التي هُيِّئت للكافرين."},{"id":"425","jozz":"4","page":"66","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"15","line_end":"15","aya_no":"132","aya_text":"وَأَطِيعُواْ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ","aya_text_emlaey":"وأطيعوا الله والرسول لعلكم ترحمون","aya_tafseer":"[132] وأطيعوا الله -أيها المؤمنون- فيما أمركم به من الطاعات وفيما نهاكم عنه من أكل الربا وغيره من الأشياء، وأطيعوا الرسول؛ لترحموا، فلا تعذبوا."},{"id":"426","jozz":"4","page":"67","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"2","aya_no":"133","aya_text":"۞ وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ أُعِدَّتۡ لِلۡمُتَّقِينَ","aya_text_emlaey":"وسارعوا إلى مغفرة من ربكم وجنة عرضها السموات والأرض أعدت للمتقين","aya_tafseer":"[133] وبادروا بطاعتكم لله ورسوله لاغتنام مغفرة عظيمة من ربكم وجنة واسعة، عرضها السموات والأرض، أعدَّها الله للمتقين."},{"id":"427","jozz":"4","page":"67","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"2","line_end":"4","aya_no":"134","aya_text":"ٱلَّذِينَ يُنفِقُونَ فِي ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلۡكَٰظِمِينَ ٱلۡغَيۡظَ وَٱلۡعَافِينَ عَنِ ٱلنَّاسِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ","aya_text_emlaey":"الذين ينفقون في السراء والضراء والكاظمين الغيظ والعافين عن الناس والله يحب المحسنين","aya_tafseer":"[134] الذين ينفقون أموالهم في اليسر والعسر، والذين يمسكون ما في أنفسهم من الغيظ بالصبر، وإذا قَدَروا عَفَوا عمَّن ظلمهم. وهذا هو الإحسان الذي يحب الله أصحابه."},{"id":"428","jozz":"4","page":"67","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"4","line_end":"7","aya_no":"135","aya_text":"وَٱلَّذِينَ إِذَا فَعَلُواْ فَٰحِشَةً أَوۡ ظَلَمُوٓاْ أَنفُسَهُمۡ ذَكَرُواْ ٱللَّهَ فَٱسۡتَغۡفَرُواْ لِذُنُوبِهِمۡ وَمَن يَغۡفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمۡ يُصِرُّواْ عَلَىٰ مَا فَعَلُواْ وَهُمۡ يَعۡلَمُونَ","aya_text_emlaey":"والذين إذا فعلوا فاحشة أو ظلموا أنفسهم ذكروا الله فاستغفروا لذنوبهم ومن يغفر الذنوب إلا الله ولم يصروا على ما فعلوا وهم يعلمون","aya_tafseer":"[135] والذين إذا ارتكبوا ذنباً كبيراً أو ظلموا أنفسهم بارتكاب ما دونه، ذكروا وعد الله ووعيده فلجؤوا إلى ربهم تائبين، يطلبون منه أن يغفر لهم ذنوبهم، وهم موقنون أنه لا يغفر الذنوب إلا الله، فهم لذلك لا يقيمون على معصية، وهم يعلمون أنهم إن تابوا تاب الله عليهم."},{"id":"429","jozz":"4","page":"67","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"7","line_end":"9","aya_no":"136","aya_text":"أُوْلَٰٓئِكَ جَزَآؤُهُم مَّغۡفِرَةٞ مِّن رَّبِّهِمۡ وَجَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ","aya_text_emlaey":"أولئك جزاؤهم مغفرة من ربهم وجنات تجري من تحتها الأنهار خالدين فيها ونعم أجر العاملين","aya_tafseer":"[136] أولئك الموصوفون بتلك الصفات العظيمة جزاؤهم أن يستر الله ذنوبهم، ولهم جنات تجري من تحت أشجارها وقصورها المياه العذبة، خالدين فيها لا يخرجون منها أبداً. ونِعْمَ أجر العاملين المغفرة والجنة."},{"id":"430","jozz":"4","page":"67","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"9","line_end":"10","aya_no":"137","aya_text":"قَدۡ خَلَتۡ مِن قَبۡلِكُمۡ سُنَنٞ فَسِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ","aya_text_emlaey":"قد خلت من قبلكم سنن فسيروا في الأرض فانظروا كيف كان عاقبة المكذبين","aya_tafseer":"[137] يخاطب الله المؤمنين لمَّا أُصيبوا يوم «أُحد» تعزية لهم بأنه قد مضت من قبلكم أمم، ابتُلي المؤمنون منهم بقتال الكافرين فكانت العاقبة لهم، فسيروا في الأرض معتبرين بما آل إليه أمر أولئك المكذبين بالله ورسله."},{"id":"431","jozz":"4","page":"67","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"11","line_end":"11","aya_no":"138","aya_text":"هَٰذَا بَيَانٞ لِّلنَّاسِ وَهُدٗى وَمَوۡعِظَةٞ لِّلۡمُتَّقِينَ","aya_text_emlaey":"هذا بيان للناس وهدى وموعظة للمتقين","aya_tafseer":"[138] هذا القرآن بيان وإرشاد إلى طريق الحق، وتذكير تخشع له قلوب المتقين، وهم الذين يخشون الله، وخُصُّوا بذلك؛ لأنهم هم المنتفعون به دون غيرهم."},{"id":"432","jozz":"4","page":"67","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"12","aya_no":"139","aya_text":"وَلَا تَهِنُواْ وَلَا تَحۡزَنُواْ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ إِن كُنتُم مُّؤۡمِنِينَ","aya_text_emlaey":"ولا تهنوا ولا تحزنوا وأنتم الأعلون إن كنتم مؤمنين","aya_tafseer":"[139] ولا تَضْعُفوا -أيها المؤمنون- عن قتال عدوكم، ولا تحزنوا لما أصابكم في «أُحد»، وأنتم الغالبون والعاقبة لكم، إن كنتم مصدقين بالله ورسوله، متَّبعين شرعه."},{"id":"433","jozz":"4","page":"67","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"13","line_end":"15","aya_no":"140","aya_text":"إِن يَمۡسَسۡكُمۡ قَرۡحٞ فَقَدۡ مَسَّ ٱلۡقَوۡمَ قَرۡحٞ مِّثۡلُهُۥۚ وَتِلۡكَ ٱلۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ ٱلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَتَّخِذَ مِنكُمۡ شُهَدَآءَۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ","aya_text_emlaey":"إن يمسسكم قرح فقد مس القوم قرح مثله وتلك الأيام نداولها بين الناس وليعلم الله الذين آمنوا ويتخذ منكم شهداء والله لا يحب الظالمين","aya_tafseer":"[140] إن أصابتكم -أيها المؤمنون -جراح أو قتل في غزوة «أُحد» فحزنتم لذلك، فقد أصاب المشركين جراح وقتل مثل ذلك في غزوة «بدر». وتلك الأيام يُصَرِّفها الله بين الناس، نصر مرة وهزيمة أخرى؛ لما في ذلك من الحكمة، حتى يظهر ما علمه الله في الأزل؛ ليميز الله المؤمن الصادق مِن غيره، ويُكْرِمَ أقواماً منكم بالشهادة. والله لا يحب الذين ظلموا أنفسهم، وقعدوا عن القتال في سبيله."},{"id":"434","jozz":"4","page":"68","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"1","aya_no":"141","aya_text":"وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَيَمۡحَقَ ٱلۡكَٰفِرِينَ","aya_text_emlaey":"وليمحص الله الذين آمنوا ويمحق الكافرين","aya_tafseer":"[141] وهذه الهزيمة التي وقعت في «أُحد» كانت اختباراً وتصفية للمؤمنين، وتخليصاً لهم من المنافقين وهلاكاً للكافرين."},{"id":"435","jozz":"4","page":"68","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"3","aya_no":"142","aya_text":"أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَعۡلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُواْ مِنكُمۡ وَيَعۡلَمَ ٱلصَّٰبِرِينَ","aya_text_emlaey":"أم حسبتم أن تدخلوا الجنة ولما يعلم الله الذين جاهدوا منكم ويعلم الصابرين","aya_tafseer":"[142] يا أصحاب محمد -صلى الله عليه وسلم- أظننتم أن تدخلوا الجنة، ولم تُبْتَلوا بالقتال والشدائد؟ لا يحصل لكم دخولها حتى تُبْتلوا، ويعلم الله علماً ظاهراً للخلق المجاهدين منكم في سبيله، والصابرين على مقاومة الأعداء."},{"id":"436","jozz":"4","page":"68","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"3","line_end":"4","aya_no":"143","aya_text":"وَلَقَدۡ كُنتُمۡ تَمَنَّوۡنَ ٱلۡمَوۡتَ مِن قَبۡلِ أَن تَلۡقَوۡهُ فَقَدۡ رَأَيۡتُمُوهُ وَأَنتُمۡ تَنظُرُونَ","aya_text_emlaey":"ولقد كنتم تمنون الموت من قبل أن تلقوه فقد رأيتموه وأنتم تنظرون","aya_tafseer":"[143] ولقد كنتم -أيها المؤمنون- قبل غزوة «أُحد» تتمنون لقاء العدو؛ لتنالوا شرف الجهاد والاستشهاد في سبيل الله الذي حَظِي به إخوانكم في غزوة «بدر»، فها هو ذا قد حصل لكم الذي تمنيتموه وطلبتموه، فدونكم فقاتلوا وصابروا."},{"id":"437","jozz":"4","page":"68","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"4","line_end":"7","aya_no":"144","aya_text":"وَمَا مُحَمَّدٌ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُۚ أَفَإِيْن مَّاتَ أَوۡ قُتِلَ ٱنقَلَبۡتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡۚ وَمَن يَنقَلِبۡ عَلَىٰ عَقِبَيۡهِ فَلَن يَضُرَّ ٱللَّهَ شَيۡـٔٗاۚ وَسَيَجۡزِي ٱللَّهُ ٱلشَّٰكِرِينَ","aya_text_emlaey":"وما محمد إلا رسول قد خلت من قبله الرسل أفإن مات أو قتل انقلبتم على أعقابكم ومن ينقلب على عقبيه فلن يضر الله شيئا وسيجزي الله الشاكرين","aya_tafseer":"[144] وما محمد -صلى الله عليه وسلم- إلا رسول من جنس الرسل الذين قبله يبلغ رسالة ربه. أفإن مات بانقضاء أجله، أو قُتِل كما أشاعه الأعداء رجعتم عن دينكم، وتركتم ما جاءكم به نبيكم؟ ومن يرجِعْ منكم عن دينه فلن يضر الله شيئاً، إنما يضر نفسه ضرراً عظيماً. أما مَن ثبت على الإيمان وشكر ربه على نعمة الإسلام، فإن الله يجزيه أحسن الجزاء."},{"id":"438","jozz":"4","page":"68","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"7","line_end":"10","aya_no":"145","aya_text":"وَمَا كَانَ لِنَفۡسٍ أَن تَمُوتَ إِلَّا بِإِذۡنِ ٱللَّهِ كِتَٰبٗا مُّؤَجَّلٗاۗ وَمَن يُرِدۡ ثَوَابَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا وَمَن يُرِدۡ ثَوَابَ ٱلۡأٓخِرَةِ نُؤۡتِهِۦ مِنۡهَاۚ وَسَنَجۡزِي ٱلشَّٰكِرِينَ","aya_text_emlaey":"وما كان لنفس أن تموت إلا بإذن الله كتابا مؤجلا ومن يرد ثواب الدنيا نؤته منها ومن يرد ثواب الآخرة نؤته منها وسنجزي الشاكرين","aya_tafseer":"[145] لن يموت أحد إلَّا بإذن الله وقدره وحتى يستوفي المدة التي قدَّرها الله له، كتب الله ذلك كتاباً مؤقتاً، لا يتقدم على أجله ولا يتأخر. ومن يطلب بعمله عَرَض الدنيا، نعطه ما قسمناه له من رزق، ولا حظَّ له في الآخرة، ومن يطلب بعمله الجزاء من الله في الآخرة نمنحه ما طلبه، ونؤته جزاءه وافراً مع ما لَه في الدنيا من رزق مقسوم، فهذا قد شَكَرَنا بطاعته وجهاده، وسنجزي الشاكرين خيراً."},{"id":"439","jozz":"4","page":"68","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"10","line_end":"12","aya_no":"146","aya_text":"وَكَأَيِّن مِّن نَّبِيّٖ قَٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٞ فَمَا وَهَنُواْ لِمَآ أَصَابَهُمۡ فِي سَبِيلِ ٱللَّهِ وَمَا ضَعُفُواْ وَمَا ٱسۡتَكَانُواْۗ وَٱللَّهُ يُحِبُّ ٱلصَّٰبِرِينَ","aya_text_emlaey":"وكأين من نبي قاتل معه ربيون كثير فما وهنوا لما أصابهم في سبيل الله وما ضعفوا وما استكانوا والله يحب الصابرين","aya_tafseer":"[146] كثير من الأنبياء السابقين قاتل معهم جموع كثيرة من أصحابهم، فما ضعفوا لِمَا نزل بهم من جروح أو قتل؛ لأن ذلك في سبيل ربهم، وما عَجَزوا، ولا خضعوا لعدوهم، إنما صبروا على ما أصابهم. والله يحب الصابرين."},{"id":"440","jozz":"4","page":"68","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"14","aya_no":"147","aya_text":"وَمَا كَانَ قَوۡلَهُمۡ إِلَّآ أَن قَالُواْ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِيٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ","aya_text_emlaey":"وما كان قولهم إلا أن قالوا ربنا اغفر لنا ذنوبنا وإسرافنا في أمرنا وثبت أقدامنا وانصرنا على القوم الكافرين","aya_tafseer":"[147] وما كان قول هؤلاء الصابرين إلا أن قالوا: ربنا اغفر لنا ذنوبنا، وما وقع منا مِن تجاوزٍ في أمر ديننا، وثَبِّت أقدامنا حتى لا نفرَّ من قتال عدونا، وانصرنا على مَن جحد وحدانيتك ونبوة أنبيائك."},{"id":"441","jozz":"4","page":"68","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"14","line_end":"15","aya_no":"148","aya_text":"فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنۡيَا وَحُسۡنَ ثَوَابِ ٱلۡأٓخِرَةِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ","aya_text_emlaey":"فآتاهم الله ثواب الدنيا وحسن ثواب الآخرة والله يحب المحسنين","aya_tafseer":"[148] فأعطى الله أولئك الصابرين جزاءهم في الدنيا بالنصر على أعدائهم، وبالتمكين لهم في الأرض، وبالجزاء الحسن العظيم في الآخرة، وهو جنات النعيم. والله يحب كلَّ مَن أحسن عبادته لربه ومعاملته لخلقه."},{"id":"442","jozz":"4","page":"69","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"2","aya_no":"149","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ ٱلَّذِينَ كَفَرُواْ يَرُدُّوكُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ","aya_text_emlaey":"ياأيها الذين آمنوا إن تطيعوا الذين كفروا يردوكم على أعقابكم فتنقلبوا خاسرين","aya_tafseer":"[149] يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه إن تطيعوا الذين جحدوا أُلوهيتي، ولم يؤمنوا برسلي من اليهود والنصارى والمنافقين والمشركين فيما يأمرونكم به وينهَوْنكم عنه، يضلوكم عن طريق الحق، وترتدُّوا عن دينكم، فتعودوا بالخسران المبين والهلاك المحقق."},{"id":"443","jozz":"4","page":"69","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"3","line_end":"3","aya_no":"150","aya_text":"بَلِ ٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ خَيۡرُ ٱلنَّٰصِرِينَ","aya_text_emlaey":"بل الله مولاكم وهو خير الناصرين","aya_tafseer":"[150] إنهم لن ينصروكم، بل الله ناصركم، وهو خير ناصر، فلا يحتاج معه إلى نصرة أحد."},{"id":"444","jozz":"4","page":"69","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"3","line_end":"6","aya_no":"151","aya_text":"سَنُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ بِمَآ أَشۡرَكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗاۖ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَبِئۡسَ مَثۡوَى ٱلظَّٰلِمِينَ","aya_text_emlaey":"سنلقي في قلوب الذين كفروا الرعب بما أشركوا بالله ما لم ينـزل به سلطانا ومأواهم النار وبئس مثوى الظالمين","aya_tafseer":"[151] سنقذف في قلوب الذين كفروا أشدَّ الفزع والخوف؛ بسبب إشراكهم بالله آلهة مزعومة، ليس لهم دليل أو برهان على استحقاقها للعبادة مع الله، فحالتهم في الدنيا: رعب وهلع من المؤمنين، أما مكانهم في الآخرة الذي يأوون إليه فهو النار؛ وذلك بسبب ظلمهم وعدوانهم، وساء هذا المقام مقاماً لهم."},{"id":"445","jozz":"4","page":"69","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"6","line_end":"11","aya_no":"152","aya_text":"وَلَقَدۡ صَدَقَكُمُ ٱللَّهُ وَعۡدَهُۥٓ إِذۡ تَحُسُّونَهُم بِإِذۡنِهِۦۖ حَتَّىٰٓ إِذَا فَشِلۡتُمۡ وَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَعَصَيۡتُم مِّنۢ بَعۡدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَۚ مِنكُم مَّن يُرِيدُ ٱلدُّنۡيَا وَمِنكُم مَّن يُرِيدُ ٱلۡأٓخِرَةَۚ ثُمَّ صَرَفَكُمۡ عَنۡهُمۡ لِيَبۡتَلِيَكُمۡۖ وَلَقَدۡ عَفَا عَنكُمۡۗ وَٱللَّهُ ذُو فَضۡلٍ عَلَى ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"ولقد صدقكم الله وعده إذ تحسونهم بإذنه حتى إذا فشلتم وتنازعتم في الأمر وعصيتم من بعد ما أراكم ما تحبون منكم من يريد الدنيا ومنكم من يريد الآخرة ثم صرفكم عنهم ليبتليكم ولقد عفا عنكم والله ذو فضل على المؤمنين ","aya_tafseer":"[152] ولقد حقق الله لكم ما وعدكم به من نصر، حين كنتم تقتلون الكفار في غزوة «أُحد» بإذنه تعالى، حتى إذا جَبُنتم وضعفتم عن القتال واختلفتم: هل تبقون في مواقعكم أو تتركونها لجمع الغنائم مع مَن يجمعها؟ وعصيتم أمر رسولكم حين أمركم ألا تفارقوا أماكنكم بأي حال، حلَّت بكم الهزيمة من بعد ما أراكم ما تحبون من النصر، وتبيَّن أن منكم مَن يريد الغنائم، وأن منكم مَن يطلب الآخرة وثوابها، ثم صرف الله وجوهكم عن عدوكم؛ ليختبركم، وقد علم الله ندمكم وتوبتكم فعفا عنكم، والله ذو فضل عظيم على المؤمنين."},{"id":"446","jozz":"4","page":"69","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"15","aya_no":"153","aya_text":"۞ إِذۡ تُصۡعِدُونَ وَلَا تَلۡوُۥنَ عَلَىٰٓ أَحَدٖ وَٱلرَّسُولُ يَدۡعُوكُمۡ فِيٓ أُخۡرَىٰكُمۡ فَأَثَٰبَكُمۡ غَمَّۢا بِغَمّٖ لِّكَيۡلَا تَحۡزَنُواْ عَلَىٰ مَا فَاتَكُمۡ وَلَا مَآ أَصَٰبَكُمۡۗ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ","aya_text_emlaey":"إذ تصعدون ولا تلوون على أحد والرسول يدعوكم في أخراكم فأثابكم غما بغم لكيلا تحزنوا على ما فاتكم ولا ما أصابكم والله خبير بما تعملون","aya_tafseer":"[153] اذكروا -يا أصحاب محمد صلى الله عليه وسلم- ما كان مِن أمركم حين أخذتم تصعدون الجبل هاربين من أعدائكم، ولا تلتفتون إلى أحد لِمَا اعتراكم من الدهشة والخوف والرعب، ورسول الله -صلى الله عليه وسلم- ثابت في الميدان يناديكم من خلفكم قائلاً: إليَّ عبادَ الله، وأنتم لا تسمعون ولا تنظرون، فكان جزاؤكم أن أنزل الله بكم ألماً وضيقاً وغمّاً؛ لكي لا تحزنوا على ما فاتكم من نصر وغنيمة، ولا ما حلَّ بكم من خوف وهزيمة. والله خبير بجميع أعمالكم، لا يخفى عليه منها شيء."},{"id":"447","jozz":"4","page":"70","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"8","aya_no":"154","aya_text":"ثُمَّ أَنزَلَ عَلَيۡكُم مِّنۢ بَعۡدِ ٱلۡغَمِّ أَمَنَةٗ نُّعَاسٗا يَغۡشَىٰ طَآئِفَةٗ مِّنكُمۡۖ وَطَآئِفَةٞ قَدۡ أَهَمَّتۡهُمۡ أَنفُسُهُمۡ يَظُنُّونَ بِٱللَّهِ غَيۡرَ ٱلۡحَقِّ ظَنَّ ٱلۡجَٰهِلِيَّةِۖ يَقُولُونَ هَل لَّنَا مِنَ ٱلۡأَمۡرِ مِن شَيۡءٖۗ قُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ يُخۡفُونَ فِيٓ أَنفُسِهِم مَّا لَا يُبۡدُونَ لَكَۖ يَقُولُونَ لَوۡ كَانَ لَنَا مِنَ ٱلۡأَمۡرِ شَيۡءٞ مَّا قُتِلۡنَا هَٰهُنَاۗ قُل لَّوۡ كُنتُمۡ فِي بُيُوتِكُمۡ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيۡهِمُ ٱلۡقَتۡلُ إِلَىٰ مَضَاجِعِهِمۡۖ وَلِيَبۡتَلِيَ ٱللَّهُ مَا فِي صُدُورِكُمۡ وَلِيُمَحِّصَ مَا فِي قُلُوبِكُمۡۚ وَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ","aya_text_emlaey":"ثم أنـزل عليكم من بعد الغم أمنة نعاسا يغشى طائفة منكم وطائفة قد أهمتهم أنفسهم يظنون بالله غير الحق ظن الجاهلية يقولون هل لنا من الأمر من شيء قل إن الأمر كله لله يخفون في أنفسهم ما لا يبدون لك يقولون لو كان لنا من الأمر شيء ما قتلنا هاهنا قل لو كنتم في بيوتكم لبرز الذين كتب عليهم القتل إلى مضاجعهم وليبتلي الله ما في صدوركم وليمحص ما في قلوبكم والله عليم بذات الصدور","aya_tafseer":"[154] ثم كان من رحمة الله بالمؤمنين المخلصين أن ألقى في قلوبهم -من بعد ما نزل بها مِن همٍّ وغمٍّ- اطمئناناً وثقة في وعد الله، وكان من أثره نعاس غَشِيَ طائفة منهم، وهم أهل الإخلاص واليقين، وطائفة أُخرى أهمَّهم خلاص أنفسهم خاصة، وضَعُفت عزيمتهم وشُغِلوا بأنفسهم، وأساؤوا الظن بربهم وبدينه وبنبيه، وظنوا أن الله لا يُتِمُّ أمر رسوله، وأن الإسلام لن تقوم له قائمة، ولذلك تراهم نادمين على خروجهم، يقول بعضهم لبعض: هل كان لنا من اختيار في الخروج للقتال؟ قل لهم -أيها الرسول-: إن الأمر كلَّه لله، فهو الذي قدَّر خروجكم وما حدث لكم، وهم يُخْفون في أنفسهم ما لا يظهرونه لك من الحسرة على خروجهم للقتال، يقولون: لو كان لنا أدنى اختيار ما قُتِلْنا هاهنا. قل لهم: إن الآجال بيد الله، ولو كنتم في بيوتكم، وقدَّر الله أنكم تموتون، لخرج الذين كتب الله عليهم الموت إلى حيث يُقْتلون، وما جعل الله ذلك إلا ليختبر ما في صدوركم من الشك والنفاق، وليميز الخبيث من الطيب، ويظهر أمر المؤمن من المنافق للناس في الأقوال والأفعال. والله عليم بما في صدور خلقه، لا يخفى عليه شيء من أمورهم."},{"id":"448","jozz":"4","page":"70","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"10","aya_no":"155","aya_text":"إِنَّ ٱلَّذِينَ تَوَلَّوۡاْ مِنكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ إِنَّمَا ٱسۡتَزَلَّهُمُ ٱلشَّيۡطَٰنُ بِبَعۡضِ مَا كَسَبُواْۖ وَلَقَدۡ عَفَا ٱللَّهُ عَنۡهُمۡۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ","aya_text_emlaey":"إن الذين تولوا منكم يوم التقى الجمعان إنما استزلهم الشيطان ببعض ما كسبوا ولقد عفا الله عنهم إن الله غفور حليم","aya_tafseer":"[155] إن الذين فرُّوا منكم -يا أصحاب محمد صلى الله عليه وسلم- عن القتال يوم التقى المؤمنون والمشركون في غزوة «أُحد»، إنما أوقعهم الشيطان في هذا الذنب ببعض ما عملوا من الذنوب، ولقد تجاوز الله عنهم فلم يعاقبهم. إن الله غفور للمذنبين التائبين، حليم لا يعاجل من عصاه بالعقوبة."},{"id":"449","jozz":"4","page":"70","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"10","line_end":"14","aya_no":"156","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَكُونُواْ كَٱلَّذِينَ كَفَرُواْ وَقَالُواْ لِإِخۡوَٰنِهِمۡ إِذَا ضَرَبُواْ فِي ٱلۡأَرۡضِ أَوۡ كَانُواْ غُزّٗى لَّوۡ كَانُواْ عِندَنَا مَا مَاتُواْ وَمَا قُتِلُواْ لِيَجۡعَلَ ٱللَّهُ ذَٰلِكَ حَسۡرَةٗ فِي قُلُوبِهِمۡۗ وَٱللَّهُ يُحۡيِۦ وَيُمِيتُۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ","aya_text_emlaey":"ياأيها الذين آمنوا لا تكونوا كالذين كفروا وقالوا لإخوانهم إذا ضربوا في الأرض أو كانوا غزى لو كانوا عندنا ما ماتوا وما قتلوا ليجعل الله ذلك حسرة في قلوبهم والله يحيي ويميت والله بما تعملون بصير","aya_tafseer":"[156] يا أيها الذين صَدَّقوا الله ورسوله وعملوا بشرعه لا تُشابهوا الكافرين الذين لا يؤمنون بربهم، فهم يقولون لإخوانهم من أهل الكفر إذا خرجوا يبحثون في أرض الله عن معاشهم أو كانوا مع الغزاة المقاتلين فماتوا أو قُتِلوا: لو لم يخرج هؤلاء ولم يقاتلوا وأقاموا معنا ما ماتوا وما قُتِلوا. وهذا القول يزيدهم ألماً وحزناً وحسرة تستقر في قلوبهم، أما المؤمنون فإنهم يعلمون أن ذلك بقدر الله فيهدي الله قلوبهم، ويخفف عنهم المصيبة، والله يحيي مَن قدَّر له الحياة -وإن كان مسافراً أو غازياً- ويميت مَنِ انتهى أجله وإن كان مقيماً. والله بكل ما تعملونه بصير، فيجازيكم به."},{"id":"450","jozz":"4","page":"70","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"14","line_end":"15","aya_no":"157","aya_text":"وَلَئِن قُتِلۡتُمۡ فِي سَبِيلِ ٱللَّهِ أَوۡ مُتُّمۡ لَمَغۡفِرَةٞ مِّنَ ٱللَّهِ وَرَحۡمَةٌ خَيۡرٞ مِّمَّا يَجۡمَعُونَ","aya_text_emlaey":"ولئن قتلتم في سبيل الله أو متم لمغفرة من الله ورحمة خير مما يجمعون","aya_tafseer":"[157] ولئن قُتِلتم -أيها المؤمنون- وأنتم تجاهدون في سبيل الله أو متم في أثناء القتال، ليغفرن الله لكم ذنوبكم، وليرحمنكم رحمة من عنده، فتفوزون بجنات النعيم، وذلك خير من الدنيا وما يجمعه أهلها."},{"id":"451","jozz":"4","page":"71","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"1","aya_no":"158","aya_text":"وَلَئِن مُّتُّمۡ أَوۡ قُتِلۡتُمۡ لَإِلَى ٱللَّهِ تُحۡشَرُونَ","aya_text_emlaey":"ولئن متم أو قتلتم لإلى الله تحشرون","aya_tafseer":"[158] ولئن انقضت آجالكم في هذه الحياة الدنيا، فمتم على فُرُشكم، أو قتلتم في ساحة القتال، لإلى الله وحده تُحشرون، فيجازيكم بأعمالكم."},{"id":"452","jozz":"4","page":"71","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"4","aya_no":"159","aya_text":"فَبِمَا رَحۡمَةٖ مِّنَ ٱللَّهِ لِنتَ لَهُمۡۖ وَلَوۡ كُنتَ فَظًّا غَلِيظَ ٱلۡقَلۡبِ لَٱنفَضُّواْ مِنۡ حَوۡلِكَۖ فَٱعۡفُ عَنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمۡ وَشَاوِرۡهُمۡ فِي ٱلۡأَمۡرِۖ فَإِذَا عَزَمۡتَ فَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَوَكِّلِينَ","aya_text_emlaey":"فبما رحمة من الله لنت لهم ولو كنت فظا غليظ القلب لانفضوا من حولك فاعف عنهم واستغفر لهم وشاورهم في الأمر فإذا عزمت فتوكل على الله إن الله يحب المتوكلين","aya_tafseer":"[159] فبرحمة من الله لك ولأصحابك - أيها النبي - منَّ الله عليك فكنت رفيقاً بهم، ولو كنت سيِّئ الخُلق قاسي القلب، لانصَرَفَ أصحابك من حولك، فلا تؤاخذهم بما كان منهم في غزوة «أُحد»، واسأل الله -أيها النبي- أن يغفر لهم، وشاورهم في الأمور التي تحتاج إلى مشورة، فإذا عزمت على أمر من الأمور -بعد الاستشارة- فأَمْضِه معتمداً على الله وحده، إن الله يحب المتوكلين عليه."},{"id":"453","jozz":"4","page":"71","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"4","line_end":"6","aya_no":"160","aya_text":"إِن يَنصُرۡكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمۡۖ وَإِن يَخۡذُلۡكُمۡ فَمَن ذَا ٱلَّذِي يَنصُرُكُم مِّنۢ بَعۡدِهِۦۗ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ","aya_text_emlaey":"إن ينصركم الله فلا غالب لكم وإن يخذلكم فمن ذا الذي ينصركم من بعده وعلى الله فليتوكل المؤمنون","aya_tafseer":"[160] إن يمددكم الله بنصره ومعونته فلا أحد يستطيع أن يغلبكم، وإن يخذلكم فمن هذا الذي يستطيع أن ينصركم من بعد خِذْلانه لكم؟ وعلى الله وحده فليتوكل المؤمنون."},{"id":"454","jozz":"4","page":"71","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"6","line_end":"8","aya_no":"161","aya_text":"وَمَا كَانَ لِنَبِيٍّ أَن يَغُلَّۚ وَمَن يَغۡلُلۡ يَأۡتِ بِمَا غَلَّ يَوۡمَ ٱلۡقِيَٰمَةِۚ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسٖ مَّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ","aya_text_emlaey":"وما كان لنبي أن يغل ومن يغلل يأت بما غل يوم القيامة ثم توفى كل نفس ما كسبت وهم لا يظلمون","aya_tafseer":"[161] وما كان لنبيٍّ أن يَخُونَ أصحابه بأن يأخذ شيئاً من الغنيمة غير ما اختصه الله به، ومن يفعل ذلك منكم يأت بما أخذه حاملاً له يوم القيامة؛ ليُفضَح به في الموقف المشهود، ثم تُعطى كل نفس جزاءَ ما كسبت وافياً غير منقوص دون ظلم."},{"id":"455","jozz":"4","page":"71","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"9","aya_no":"162","aya_text":"أَفَمَنِ ٱتَّبَعَ رِضۡوَٰنَ ٱللَّهِ كَمَنۢ بَآءَ بِسَخَطٖ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ","aya_text_emlaey":"أفمن اتبع رضوان الله كمن باء بسخط من الله ومأواه جهنم وبئس المصير","aya_tafseer":"[162] لا يستوي من كان قصده رضوان الله ومن هو مُكِبٌّ على المعاصي، مسخط لربه، فاستحق بذلك سكنَ جهنم، وبئس المصير."},{"id":"456","jozz":"4","page":"71","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"10","line_end":"10","aya_no":"163","aya_text":"هُمۡ دَرَجَٰتٌ عِندَ ٱللَّهِۗ وَٱللَّهُ بَصِيرُۢ بِمَا يَعۡمَلُونَ","aya_text_emlaey":"هم درجات عند الله والله بصير بما يعملون","aya_tafseer":"[163] أصحاب الجنة المتبعون لما يرضي الله متفاوتون في الدرجات، وأصحاب النار المتبعون لما يسخط الله متفاوتون في الدركات، لا يستوون. والله بصير بأعمالهم لا يخفى عليه منها شيء."},{"id":"457","jozz":"4","page":"71","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"10","line_end":"13","aya_no":"164","aya_text":"لَقَدۡ مَنَّ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ إِذۡ بَعَثَ فِيهِمۡ رَسُولٗا مِّنۡ أَنفُسِهِمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلٖ مُّبِينٍ","aya_text_emlaey":"لقد من الله على المؤمنين إذ بعث فيهم رسولا من أنفسهم يتلو عليهم آياته ويزكيهم ويعلمهم الكتاب والحكمة وإن كانوا من قبل لفي ضلال مبين","aya_tafseer":"[164] لقد أنعم الله على المؤمنين من العرب؛ إذ بعث فيهم رسولاً من أنفسهم، يتلو عليهم آيات القرآن، ويطهرهم من الشرك والأخلاق الفاسدة، ويعلمهم القرآن والسنة، وإن كانوا من قبل هذا الرسول لفي غيٍّ وجهل ظاهر."},{"id":"458","jozz":"4","page":"71","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"13","line_end":"15","aya_no":"165","aya_text":"أَوَلَمَّآ أَصَٰبَتۡكُم مُّصِيبَةٞ قَدۡ أَصَبۡتُم مِّثۡلَيۡهَا قُلۡتُمۡ أَنَّىٰ هَٰذَاۖ قُلۡ هُوَ مِنۡ عِندِ أَنفُسِكُمۡۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","aya_text_emlaey":"أو لما أصابتكم مصيبة قد أصبتم مثليها قلتم أنى هذا قل هو من عند أنفسكم إن الله على كل شيء قدير","aya_tafseer":"[165] أو لما أصابتكم -أيها المؤمنون- مصيبة، وهي ما أُصيب منكم يوم «أُحد» قد أصبتم مثليها من المشركين في يوم «بدْر»، قلتم متعجبين: كيف يكون هذا ونحن مسلمون ورسول الله -صلى الله عليه وسلم- فينا وهؤلاء مشركون؟ قل لهم -أيها النبي-: هذا الذي أصابكم هو من عند أنفسكم؛ بسبب مخالفتكم أَمْرَ رسولكم وإقبالكم على جمع الغنائم. إن الله يفعل ما يشاء ويحكم ما يريد، لا معقِّب لحكمه."},{"id":"459","jozz":"4","page":"72","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"1","aya_no":"166","aya_text":"وَمَآ أَصَٰبَكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ فَبِإِذۡنِ ٱللَّهِ وَلِيَعۡلَمَ ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"وما أصابكم يوم التقى الجمعان فبإذن الله وليعلم المؤمنين","aya_tafseer":"[166] وما وقع بكم مِن جراح أو قتل في غزوة «أُحد» يوم التقى جَمْعُ المؤمنين وجمع المشركين فكان النصر للمؤمنين أولاً ثم للمشركين ثانياً، فذلك كله بقضاء الله وقدره، وليَظْهر ما علمه الله في الأزل؛ ليميز المؤمنين الصادقين منكم."},{"id":"460","jozz":"4","page":"72","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"2","line_end":"5","aya_no":"167","aya_text":"وَلِيَعۡلَمَ ٱلَّذِينَ نَافَقُواْۚ وَقِيلَ لَهُمۡ تَعَالَوۡاْ قَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ أَوِ ٱدۡفَعُواْۖ قَالُواْ لَوۡ نَعۡلَمُ قِتَالٗا لَّٱتَّبَعۡنَٰكُمۡۗ هُمۡ لِلۡكُفۡرِ يَوۡمَئِذٍ أَقۡرَبُ مِنۡهُمۡ لِلۡإِيمَٰنِۚ يَقُولُونَ بِأَفۡوَٰهِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ وَٱللَّهُ أَعۡلَمُ بِمَا يَكۡتُمُونَ","aya_text_emlaey":"وليعلم الذين نافقوا وقيل لهم تعالوا قاتلوا في سبيل الله أو ادفعوا قالوا لو نعلم قتالا لاتبعناكم هم للكفر يومئذ أقرب منهم للإيمان يقولون بأفواههم ما ليس في قلوبهم والله أعلم بما يكتمون","aya_tafseer":"[167] ولِيعلم المنافقين الذين كشف الله ما في قلوبهم حين قال المؤمنون لهم: تعالوا قاتلوا معنا في سبيل الله، أو كونوا عوناً لنا بتكثيركم سوادنا، فقالوا: لو نعلم أنكم تقاتلون أحداً لكنا معكم عليهم، هم للكفر في هذا اليوم أقرب منهم للإيمان؛ لأنهم يقولون بأفواههم ما ليس في قلوبهم. والله أعلم بما يُخفون في صدورهم."},{"id":"461","jozz":"4","page":"72","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"5","line_end":"7","aya_no":"168","aya_text":"ٱلَّذِينَ قَالُواْ لِإِخۡوَٰنِهِمۡ وَقَعَدُواْ لَوۡ أَطَاعُونَا مَا قُتِلُواْۗ قُلۡ فَٱدۡرَءُواْ عَنۡ أَنفُسِكُمُ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ","aya_text_emlaey":"الذين قالوا لإخوانهم وقعدوا لو أطاعونا ما قتلوا قل فادرءوا عن أنفسكم الموت إن كنتم صادقين","aya_tafseer":"[168] هؤلاء المنافقون هم الذين قعدوا وقالوا لإخوانهم الذين أصيبوا مع المسلمين في حربهم المشركين يوم «أُحد»: لو أطاعَنا هؤلاء ما قتلوا. قل لهم -أيها الرسول-: فادفعوا عن أنفسكم الموت إن كنتم صادقين في دعواكم أنهم لو أطاعوكم ما قتلوا، وأنكم قد نجوتم منه بقعودكم عن القتال."},{"id":"462","jozz":"4","page":"72","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"7","line_end":"8","aya_no":"169","aya_text":"وَلَا تَحۡسَبَنَّ ٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتَۢاۚ بَلۡ أَحۡيَآءٌ عِندَ رَبِّهِمۡ يُرۡزَقُونَ","aya_text_emlaey":"ولا تحسبن الذين قتلوا في سبيل الله أمواتا بل أحياء عند ربهم يرزقون","aya_tafseer":"[169] ولا تظنَّنَّ -أيها النبي- أن الذين قتلوا في سبيل الله أموات لا يُحِسُّون شيئاً، بل هم أحياء حياة برزخية في جوار ربهم الذي جاهدوا من أجله، وماتوا في سبيله، يجري عليهم رزقهم في الجنة، ويُنَعَّمون."},{"id":"463","jozz":"4","page":"72","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"10","aya_no":"170","aya_text":"فَرِحِينَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ وَيَسۡتَبۡشِرُونَ بِٱلَّذِينَ لَمۡ يَلۡحَقُواْ بِهِم مِّنۡ خَلۡفِهِمۡ أَلَّا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ","aya_text_emlaey":"فرحين بما آتاهم الله من فضله ويستبشرون بالذين لم يلحقوا بهم من خلفهم ألا خوف عليهم ولا هم يحزنون","aya_tafseer":"[170] لقد عَمَّتهم السعادة حين مَنَّ الله عليهم، فأعطاهم مِن عظيم جوده وواسع كرمه من النعيم والرضا ما تَقَرُّ به أعينهم، وهم يفرحون بإخوانهم المجاهدين الذين فارقوهم وهم أحياء؛ ليفوزوا كما فازوا، لِعِلْمِهم أنهم سينالون من الخير الذي نالوه إذا استشهدوا في سبيل الله مخلصين له، وأن لا خوف عليهم فيما يستقبلون من أمور الآخرة، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا."},{"id":"464","jozz":"4","page":"72","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"10","line_end":"12","aya_no":"171","aya_text":"۞ يَسۡتَبۡشِرُونَ بِنِعۡمَةٖ مِّنَ ٱللَّهِ وَفَضۡلٖ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"يستبشرون بنعمة من الله وفضل وأن الله لا يضيع أجر المؤمنين","aya_tafseer":"[171] وإنهم في فرحة غامرة بما أُعطوا من نعم الله وجزيل عطائه، وأن الله لا يضيع أجر المؤمنين به، بل ينمِّيه ويزيده من فضله."},{"id":"465","jozz":"4","page":"72","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"13","aya_no":"172","aya_text":"ٱلَّذِينَ ٱسۡتَجَابُواْ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعۡدِ مَآ أَصَابَهُمُ ٱلۡقَرۡحُۚ لِلَّذِينَ أَحۡسَنُواْ مِنۡهُمۡ وَٱتَّقَوۡاْ أَجۡرٌ عَظِيمٌ","aya_text_emlaey":"الذين استجابوا لله والرسول من بعد ما أصابهم القرح للذين أحسنوا منهم واتقوا أجر عظيم","aya_tafseer":"[172] الذين لبَّوا نداء الله ورسوله وخرجوا في أعقاب المشركين إلى «حمراء الأسد» بعد هزيمتهم في غزوة «أُحد» مع ما كان بهم من آلام وجراح، وبذلوا غاية جهدهم، والتزموا بهدي نبيهم، للمحسنين منهم والمتقين ثواب عظيم."},{"id":"466","jozz":"4","page":"72","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"14","line_end":"15","aya_no":"173","aya_text":"ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِيمَٰنٗا وَقَالُواْ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ","aya_text_emlaey":"الذين قال لهم الناس إن الناس قد جمعوا لكم فاخشوهم فزادهم إيمانا وقالوا حسبنا الله ونعم الوكيل","aya_tafseer":"[173] وهم الذين قال لهم بعض المشركين: إن أبا سفيان ومن معه قد أجمعوا أمرهم على الرجوع إليكم لاستئصالكم، فاحذروهم واتقوا لقاءهم، فإنه لا طاقة لكم بهم، فزادهم ذلك التخويف يقيناً وتصديقاً بوعد الله لهم، ولم يَثْنِهم ذلك عن عزمهم، فساروا إلى حيث شاء الله، وقالوا: حسبنا الله أي: كافينا، ونِعْم الوكيل المفوَّض إليه تدبير عباده."},{"id":"467","jozz":"4","page":"73","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"2","aya_no":"174","aya_text":"فَٱنقَلَبُواْ بِنِعۡمَةٖ مِّنَ ٱللَّهِ وَفَضۡلٖ لَّمۡ يَمۡسَسۡهُمۡ سُوٓءٞ وَٱتَّبَعُواْ رِضۡوَٰنَ ٱللَّهِۗ وَٱللَّهُ ذُو فَضۡلٍ عَظِيمٍ","aya_text_emlaey":"فانقلبوا بنعمة من الله وفضل لم يمسسهم سوء واتبعوا رضوان الله والله ذو فضل عظيم","aya_tafseer":"[174] فرجعوا من «حمراء الأسد» إلى «المدينة» بنعمة من الله بالثواب الجزيل، وبفضل منه بالمنزلة العالية، وقد ازدادوا إيماناً ويقيناً، وأذلوا أعداء الله، وفازوا بالسلامة من القتل والقتال، واتبعوا رضوان الله بطاعتهم له ولرسوله. والله ذو إحسان وعطاء كثير واسع عليهم وعلى غيرهم."},{"id":"468","jozz":"4","page":"73","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"2","line_end":"3","aya_no":"175","aya_text":"إِنَّمَا ذَٰلِكُمُ ٱلشَّيۡطَٰنُ يُخَوِّفُ أَوۡلِيَآءَهُۥ فَلَا تَخَافُوهُمۡ وَخَافُونِ إِن كُنتُم مُّؤۡمِنِينَ","aya_text_emlaey":"إنما ذلكم الشيطان يخوف أولياءه فلا تخافوهم وخافون إن كنتم مؤمنين","aya_tafseer":"[175] إنَّما المثبِّط لكم في ذلك هو الشيطان جاءكم يخوِّفكم أنصاره، فلا تخافوا المشركين؛ لأنّهم ضعاف لا ناصر لهم، وخافوني بالإقبال على طاعتي إن كنتم مصدِّقين بي، ومتبعين رسولي."},{"id":"469","jozz":"4","page":"73","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"4","line_end":"6","aya_no":"176","aya_text":"وَلَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِۚ إِنَّهُمۡ لَن يَضُرُّواْ ٱللَّهَ شَيۡـٔٗاۚ يُرِيدُ ٱللَّهُ أَلَّا يَجۡعَلَ لَهُمۡ حَظّٗا فِي ٱلۡأٓخِرَةِۖ وَلَهُمۡ عَذَابٌ عَظِيمٌ","aya_text_emlaey":"ولا يحزنك الذين يسارعون في الكفر إنهم لن يضروا الله شيئا يريد الله ألا يجعل لهم حظا في الآخرة ولهم عذاب عظيم","aya_tafseer":"[176] لا يُدْخِل الحزنَ إلى قلبك -أيها الرسول- هؤلاء الكفارُ بمسارعتهم في الجحود والضلال، إنهم بذلك لن يضروا الله شيئاً، إنما يضرون أنفسهم بحرمانها حلاوة الإيمان وعظيم الثواب، يريد الله ألَّا يجعل لهم ثواباً في الآخرة؛ لأنهم انصرفوا عن دعوة الحق، ولهم عذاب شديد."},{"id":"470","jozz":"4","page":"73","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"6","line_end":"7","aya_no":"177","aya_text":"إِنَّ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلۡكُفۡرَ بِٱلۡإِيمَٰنِ لَن يَضُرُّواْ ٱللَّهَ شَيۡـٔٗاۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ","aya_text_emlaey":"إن الذين اشتروا الكفر بالإيمان لن يضروا الله شيئا ولهم عذاب أليم","aya_tafseer":"[177] إن الذين استبدلوا الكفر بالإيمان لن يضروا الله شيئاً، بل ضرر فِعْلِهم يعود على أنفسهم، ولهم في الآخرة عذاب موجع."},{"id":"471","jozz":"4","page":"73","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"7","line_end":"9","aya_no":"178","aya_text":"وَلَا يَحۡسَبَنَّ ٱلَّذِينَ كَفَرُوٓاْ أَنَّمَا نُمۡلِي لَهُمۡ خَيۡرٞ لِّأَنفُسِهِمۡۚ إِنَّمَا نُمۡلِي لَهُمۡ لِيَزۡدَادُوٓاْ إِثۡمٗاۖ وَلَهُمۡ عَذَابٞ مُّهِينٞ","aya_text_emlaey":"ولا يحسبن الذين كفروا أنما نملي لهم خير لأنفسهم إنما نملي لهم ليزدادوا إثما ولهم عذاب مهين","aya_tafseer":"[178] ولا يظننَّ الجاحدون أننا إذا أَطَلْنا أعمارهم، ومتعناهم بمُتع الدنيا، ولم نؤاخذهم بكفرهم وذنوبهم، أنهم قد نالوا بذلك خيراً لأنفسهم، إنما نؤخر عذابهم وآجالهم؛ ليزدادوا ظلماً وطغياناً، ولهم عذاب يُهينهم ويذلُّهم."},{"id":"472","jozz":"4","page":"73","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"9","line_end":"12","aya_no":"179","aya_text":"مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلۡمُؤۡمِنِينَ عَلَىٰ مَآ أَنتُمۡ عَلَيۡهِ حَتَّىٰ يَمِيزَ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِۗ وَمَا كَانَ ٱللَّهُ لِيُطۡلِعَكُمۡ عَلَى ٱلۡغَيۡبِ وَلَٰكِنَّ ٱللَّهَ يَجۡتَبِي مِن رُّسُلِهِۦ مَن يَشَآءُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۚ وَإِن تُؤۡمِنُواْ وَتَتَّقُواْ فَلَكُمۡ أَجۡرٌ عَظِيمٞ","aya_text_emlaey":"ما كان الله ليذر المؤمنين على ما أنتم عليه حتى يميز الخبيث من الطيب وما كان الله ليطلعكم على الغيب ولكن الله يجتبي من رسله من يشاء فآمنوا بالله ورسله وإن تؤمنوا وتتقوا فلكم أجر عظيم","aya_tafseer":"[179] ما كان الله لِيَدَعَكم أيها المصدِّقون بالله ورسوله العاملون بشرعه على ما أنتم عليه من التباس المؤمن منكم بالمنافق حتى يَمِيْزَ الخبيث من الطيب، فيُعرف المنافق من المؤمن الصادق. وما كان مِن حكمة الله أن يطلعكم -أيها المؤمنون- على الغيب الذي يعلمه من عباده، فتعرفوا المؤمن منهم من المنافق، ولكنه يميزهم بالمحن والابتلاء، غير أن الله تعالى يصطفي من رسله مَن يشاء؛ ليطلعه على بعض علم الغيب بوحي منه، فآمنوا بالله ورسوله، وإن تؤمنوا إيماناً صادقاً وتتقوا ربكم بطاعته، فلكم أجر عظيم عند الله."},{"id":"473","jozz":"4","page":"73","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"15","aya_no":"180","aya_text":"وَلَا يَحۡسَبَنَّ ٱلَّذِينَ يَبۡخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ هُوَ خَيۡرٗا لَّهُمۖ بَلۡ هُوَ شَرّٞ لَّهُمۡۖ سَيُطَوَّقُونَ مَا بَخِلُواْ بِهِۦ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ","aya_text_emlaey":"ولا يحسبن الذين يبخلون بما آتاهم الله من فضله هو خيرا لهم بل هو شر لهم سيطوقون ما بخلوا به يوم القيامة ولله ميراث السموات والأرض والله بما تعملون خبير","aya_tafseer":"[180] ولا يظنن الذين يبخلون بما أنعم الله به عليهم تفضلاً منه أن هذا البخل خير لهم، بل هو شرٌّ لهم؛ لأن هذا المال الذي جمعوه سيكون طوقاً من نار يوضع في أعناقهم يوم القيامة. والله سبحانه وتعالى هو مالك الملك، وهو الباقي بعد فناء جميع خلقه، وهو خبير بأعمالكم جميعها، وسيجازي كُلّاً على قَدْر استحقاقه."},{"id":"474","jozz":"4","page":"74","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"3","aya_no":"181","aya_text":"لَّقَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ فَقِيرٞ وَنَحۡنُ أَغۡنِيَآءُۘ سَنَكۡتُبُ مَا قَالُواْ وَقَتۡلَهُمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖ وَنَقُولُ ذُوقُواْ عَذَابَ ٱلۡحَرِيقِ","aya_text_emlaey":"لقد سمع الله قول الذين قالوا إن الله فقير ونحن أغنياء سنكتب ما قالوا وقتلهم الأنبياء بغير حق ونقول ذوقوا عذاب الحريق","aya_tafseer":"[181] لقد سمع الله قول اليهود الذين قالوا: إن الله فقير إلينا يطلب منا أن نقرضه أموالاً، ونحن أغنياء. سنكتب هذا القول الذي قالوه، وسنكتب أنهم راضون بما كان مِن قَتْل آبائهم لأنبياء الله ظلماً وعدواناً، وسوف نؤاخذهم بذلك في الآخرة، ونقول لهم وهم في النار يعذبون: ذوقوا عذاب النار المحرقة."},{"id":"475","jozz":"4","page":"74","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"3","line_end":"4","aya_no":"182","aya_text":"ذَٰلِكَ بِمَا قَدَّمَتۡ أَيۡدِيكُمۡ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّامٖ لِّلۡعَبِيدِ","aya_text_emlaey":"ذلك بما قدمت أيديكم وأن الله ليس بظلام للعبيد","aya_tafseer":"[182] ذلك العذاب الشديد بسبب ما قدَّمتموه في حياتكم الدنيا من المعاصي القولية والفعلية والاعتقادية، وأن الله ليس بظلام للعبيد."},{"id":"476","jozz":"4","page":"74","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"4","line_end":"7","aya_no":"183","aya_text":"ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ عَهِدَ إِلَيۡنَآ أَلَّا نُؤۡمِنَ لِرَسُولٍ حَتَّىٰ يَأۡتِيَنَا بِقُرۡبَانٖ تَأۡكُلُهُ ٱلنَّارُۗ قُلۡ قَدۡ جَآءَكُمۡ رُسُلٞ مِّن قَبۡلِي بِٱلۡبَيِّنَٰتِ وَبِٱلَّذِي قُلۡتُمۡ فَلِمَ قَتَلۡتُمُوهُمۡ إِن كُنتُمۡ صَٰدِقِينَ","aya_text_emlaey":"الذين قالوا إن الله عهد إلينا ألا نؤمن لرسول حتى يأتينا بقربان تأكله النار قل قد جاءكم رسل من قبلي بالبينات وبالذي قلتم فلم قتلتموهم إن كنتم صادقين","aya_tafseer":"[183] هؤلاء اليهود حين دُعُوا إلى الإسلام قالوا: إن الله أوصانا في التوراة ألا نصدِّق مَن جاءنا يقول: إنه رسول من الله، حتى يأتينا بصدقة يتقرب بها إلى الله، فتنزل نار من السماء فتحرقها. قل لهم -أيها الرسول-: أنتم كاذبون في قولكم؛ لأنه قد جاء آباءكم رسلٌ من قبلي بالمعجزات والدلائل على صدقهم، وبالذي قلتم من الإتيان بالقربان الذي تأكله النار، فَلِمَ قَتَل آباؤكم هؤلاء الأنبياء إن كنتم صادقين في دعواكم؟"},{"id":"477","jozz":"4","page":"74","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"9","aya_no":"184","aya_text":"فَإِن كَذَّبُوكَ فَقَدۡ كُذِّبَ رُسُلٞ مِّن قَبۡلِكَ جَآءُو بِٱلۡبَيِّنَٰتِ وَٱلزُّبُرِ وَٱلۡكِتَٰبِ ٱلۡمُنِيرِ","aya_text_emlaey":"فإن كذبوك فقد كذب رسل من قبلك جاءوا بالبينات والزبر والكتاب المنير","aya_tafseer":"[184] فإن كذَّبك -أيها الرسول- هؤلاء اليهود وغيرهم من أهل الكفر، فقد كذَّب المبطلون كثيراً من المرسلين مِن قبلك، جاؤوا أقوامهم بالمعجزات الباهرات والحجج الواضحات، والكتب السماوية التي هي نور يكشف الظلمات، والكتابِ البيِّن الواضح."},{"id":"478","jozz":"4","page":"74","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"9","line_end":"12","aya_no":"185","aya_text":"كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۗ وَإِنَّمَا تُوَفَّوۡنَ أُجُورَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۖ فَمَن زُحۡزِحَ عَنِ ٱلنَّارِ وَأُدۡخِلَ ٱلۡجَنَّةَ فَقَدۡ فَازَۗ وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا مَتَٰعُ ٱلۡغُرُورِ","aya_text_emlaey":"كل نفس ذائقة الموت وإنما توفون أجوركم يوم القيامة فمن زحزح عن النار وأدخل الجنة فقد فاز وما الحياة الدنيا إلا متاع الغرور","aya_tafseer":"[185] كل نفس لابدَّ أن تذوق الموت، وبهذا يرجع جميع الخلق إلى ربهم؛ ليحاسبهم. وإنما تُوفَّون أجوركم على أعمالكم وافية غير منقوصة يوم القيامة، فمن أكرمه ربه ونجَّاه من النار وأدخله الجنة فقد نال غاية ما يطلب. وما الحياة الدنيا إلا متعة زائلة، فلا تغترُّوا بها."},{"id":"479","jozz":"4","page":"74","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"15","aya_no":"186","aya_text":"۞ لَتُبۡلَوُنَّ فِيٓ أَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ وَلَتَسۡمَعُنَّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَمِنَ ٱلَّذِينَ أَشۡرَكُوٓاْ أَذٗى كَثِيرٗاۚ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ فَإِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ","aya_text_emlaey":"لتبلون في أموالكم وأنفسكم ولتسمعن من الذين أوتوا الكتاب من قبلكم ومن الذين أشركوا أذى كثيرا وإن تصبروا وتتقوا فإن ذلك من عزم الأمور","aya_tafseer":"[186] لتُخْتَبرُنَّ -أيُّها المؤمنون- في أموالكم بإخراج النفقات الواجبة والمستحبَّة، وبالجوائح التي تصيبها، وفي أنفسكم بما يجب عليكم من الطاعات، وما يحلُّ بكم مِن جراح أو قتل وفَقْد للأحباب؛ وذلك حتى يتميَّز المؤمن الصادق من غيره. ولتَسمعُنَّ من اليهود والنصارى والمشركين ما يؤذي أسماعكم من ألفاظ الشرك والطعن في دينكم. وإن تصبروا -أيها المؤمنون- على ذلك كله، وتتقوا الله بلزوم طاعته واجتناب معصيته، فإن ذلك من الأمور التي يُعزم عليها، وينافس فيها."},{"id":"480","jozz":"4","page":"75","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"3","aya_no":"187","aya_text":"وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكۡتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمۡ وَٱشۡتَرَوۡاْ بِهِۦ ثَمَنٗا قَلِيلٗاۖ فَبِئۡسَ مَا يَشۡتَرُونَ","aya_text_emlaey":"وإذ أخذ الله ميثاق الذين أوتوا الكتاب لتبيننه للناس ولا تكتمونه فنبذوه وراء ظهورهم واشتروا به ثمنا قليلا فبئس ما يشترون","aya_tafseer":"[187] واذكر -أيها الرسول- إذ أخذ الله العهد الموثق على الذين آتاهم الله الكتاب من اليهود والنصارى، فلليهود التوراة وللنصارى الإنجيل؛ ليعملوا بهما، ويبينوا للناس ما فيهما، ولا يكتموا ذلك ولا يخفوه، فتركوا العهد ولم يلتزموا به، وأخذوا ثمناً بخساً مقابل كتمانهم الحق وتحريفهم الكتاب، فبئس الشراء يشترون، في تضييعهم الميثاق، وتبديلهم الكتاب."},{"id":"481","jozz":"4","page":"75","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"3","line_end":"5","aya_no":"188","aya_text":"لَا تَحۡسَبَنَّ ٱلَّذِينَ يَفۡرَحُونَ بِمَآ أَتَواْ وَّيُحِبُّونَ أَن يُحۡمَدُواْ بِمَا لَمۡ يَفۡعَلُواْ فَلَا تَحۡسَبَنَّهُم بِمَفَازَةٖ مِّنَ ٱلۡعَذَابِۖ وَلَهُمۡ عَذَابٌ أَلِيمٞ","aya_text_emlaey":"لا تحسبن الذين يفرحون بما أتوا ويحبون أن يحمدوا بما لم يفعلوا فلا تحسبنهم بمفازة من العذاب ولهم عذاب أليم","aya_tafseer":"[188] ولا تظنن الذين يفرحون بما أَتَوا من أفعال قبيحة كاليهود والمنافقين وغيرهم، ويحبون أن يُثْنِيَ عليهم الناس بما لم يفعلوا، فلا تظننهم ناجين من عذاب الله في الدنيا، ولهم في الآخرة عذاب موجع. وفي الآية وعيد شديد لكل آت لفعل السوء معجب به، ولكل مفتخر بما لم يعمل؛ ليُثْنِيَ عليه الناس ويحمدوه."},{"id":"482","jozz":"4","page":"75","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"5","line_end":"6","aya_no":"189","aya_text":"وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ","aya_text_emlaey":"ولله ملك السموات والأرض والله على كل شيء قدير","aya_tafseer":"[189] ولله وحده ملك السموات والأرض وما فيهما، والله على كل شيء قدير."},{"id":"483","jozz":"4","page":"75","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"6","line_end":"8","aya_no":"190","aya_text":"إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ لَأٓيَٰتٖ لِّأُوْلِي ٱلۡأَلۡبَٰبِ","aya_text_emlaey":"إن في خلق السموات والأرض واختلاف الليل والنهار لآيات لأولي الألباب","aya_tafseer":"[190] إن في خلق السموات والأرض على غير مثال سابق، وفي تعاقُب الليل والنهار، واختلافهما طولاً وقِصَراً، لَدلائلَ وبراهين عظيمة على وحدانية الله لأصحاب العقول السليمة."},{"id":"484","jozz":"4","page":"75","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"10","aya_no":"191","aya_text":"ٱلَّذِينَ يَذۡكُرُونَ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِهِمۡ وَيَتَفَكَّرُونَ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ رَبَّنَا مَا خَلَقۡتَ هَٰذَا بَٰطِلٗا سُبۡحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ","aya_text_emlaey":"الذين يذكرون الله قياما وقعودا وعلى جنوبهم ويتفكرون في خلق السموات والأرض ربنا ما خلقت هذا باطلا سبحانك فقنا عذاب النار","aya_tafseer":"[191] الذين يذكرون الله في جميع أحوالهم: قياماً وقعوداً وعلى جنوبهم، وهم يتدبرون في خلق السموات والأرض، قائلين: يا ربَّنا ما أوجدت هذا الخلق عبثاً، فأنت منزَّه عن ذلك، فاصْرِفْ عنا عذاب النار."},{"id":"485","jozz":"4","page":"75","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"11","line_end":"12","aya_no":"192","aya_text":"رَبَّنَآ إِنَّكَ مَن تُدۡخِلِ ٱلنَّارَ فَقَدۡ أَخۡزَيۡتَهُۥۖ وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارٖ","aya_text_emlaey":"ربنا إنك من تدخل النار فقد أخزيته وما للظالمين من أنصار","aya_tafseer":"[192] يا ربَّنا نجِّنا من النار، فإنك -يا ألله- من تُدخِلْه النار بذنوبه فقد فضحته وأهنته، وما للمذنبين الظالمين لأنفسهم مِن أحد يدفع عنهم عقاب الله يوم القيامة."},{"id":"486","jozz":"4","page":"75","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"12","line_end":"14","aya_no":"193","aya_text":"رَّبَّنَآ إِنَّنَا سَمِعۡنَا مُنَادِيٗا يُنَادِي لِلۡإِيمَٰنِ أَنۡ ءَامِنُواْ بِرَبِّكُمۡ فَـَٔامَنَّاۚ رَبَّنَا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَكَفِّرۡ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلۡأَبۡرَارِ","aya_text_emlaey":"ربنا إننا سمعنا مناديا ينادي للإيمان أن آمنوا بربكم فآمنا ربنا فاغفر لنا ذنوبنا وكفر عنا سيئاتنا وتوفنا مع الأبرار","aya_tafseer":"[193] يا ربَّنا إننا سمعنا منادياً -هو نبيك محمد - صلى الله عليه وسلم- ينادي الناس للتصديق بك، والإقرار بوحدانيتك، والعمل بشرعك، فأجبنا دعوته وصدَّقْنا رسالته، فاغفر لنا ذنوبنا، واستر عيوبنا، وألحقنا بالصالحين."},{"id":"487","jozz":"4","page":"75","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"14","line_end":"15","aya_no":"194","aya_text":"رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخۡزِنَا يَوۡمَ ٱلۡقِيَٰمَةِۖ إِنَّكَ لَا تُخۡلِفُ ٱلۡمِيعَادَ","aya_text_emlaey":"ربنا وآتنا ما وعدتنا على رسلك ولا تخزنا يوم القيامة إنك لا تخلف الميعاد","aya_tafseer":"[194] يا ربَّنا أعطنا ما وعدتنا على ألسنة رسلك من نصر وتمكين وتوفيق وهداية، ولا تفضحنا بذنوبنا يوم القيامة، فإنك كريم لا تُخْلف وعداً وَعَدْتَ به عبادك."},{"id":"488","jozz":"4","page":"76","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"1","line_end":"6","aya_no":"195","aya_text":"فَٱسۡتَجَابَ لَهُمۡ رَبُّهُمۡ أَنِّي لَآ أُضِيعُ عَمَلَ عَٰمِلٖ مِّنكُم مِّن ذَكَرٍ أَوۡ أُنثَىٰۖ بَعۡضُكُم مِّنۢ بَعۡضٖۖ فَٱلَّذِينَ هَاجَرُواْ وَأُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأُوذُواْ فِي سَبِيلِي وَقَٰتَلُواْ وَقُتِلُواْ لَأُكَفِّرَنَّ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأُدۡخِلَنَّهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ ثَوَابٗا مِّنۡ عِندِ ٱللَّهِۚ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلثَّوَابِ","aya_text_emlaey":"فاستجاب لهم ربهم أني لا أضيع عمل عامل منكم من ذكر أو أنثى بعضكم من بعض فالذين هاجروا وأخرجوا من ديارهم وأوذوا في سبيلي وقاتلوا وقتلوا لأكفرن عنهم سيئاتهم ولأدخلنهم جنات تجري من تحتها الأنهار ثوابا من عند الله والله عنده حسن الثواب","aya_tafseer":"[195] فأجاب الله دعاءهم بأنه لا يضيع جهد مَن عمل منهم عملاً صالحاً، ذكراً كان أو أنثى، وهم في أُخُوَّة الدين وفي الطاعة وقَبول الأعمال سواء، فالذين هاجروا رغبةً في رضا الله تعالى، وأُخرجوا من ديارهم، وأوذوا في طاعة ربهم وعبادتهم إيّاه، وقاتلوا وقُتِلوا في سبيل الله لإعلاء كلمته، ليسترنَّ الله عليهم ما ارتكبوه من المعاصي، كما سترها عليهم في الدنيا، فلا يحاسبهم عليها، وليدخلنَّهم جنات تجري من تحت قصورها وأشجارها الأنهار جزاء من عند الله، والله عنده حسن الثواب."},{"id":"489","jozz":"4","page":"76","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"6","line_end":"7","aya_no":"196","aya_text":"لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُواْ فِي ٱلۡبِلَٰدِ","aya_text_emlaey":"لا يغرنك تقلب الذين كفروا في البلاد","aya_tafseer":"[196] لا تغتر -أيها الرسول- بما عليه أهل الكفر بالله مِن بسطة في العيش، وسَعَة في الرزق، وانتقالهم من مكان إلى مكان للتجارات وطلب الأرباح والأموال، فعمَّا قليل يزول هذا كلُّه عنهم، ويصبحون مرتهنين بأعمالهم السيئة."},{"id":"490","jozz":"4","page":"76","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"7","line_end":"7","aya_no":"197","aya_text":"مَتَٰعٞ قَلِيلٞ ثُمَّ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ","aya_text_emlaey":"متاع قليل ثم مأواهم جهنم وبئس المهاد","aya_tafseer":"[197] متاع قليل زائل، ثم يكون مصيرهم يوم القيامة إلى النار، وبئس الفراش."},{"id":"491","jozz":"4","page":"76","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"8","line_end":"10","aya_no":"198","aya_text":"لَٰكِنِ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ لَهُمۡ جَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا نُزُلٗا مِّنۡ عِندِ ٱللَّهِۗ وَمَا عِندَ ٱللَّهِ خَيۡرٞ لِّلۡأَبۡرَارِ","aya_text_emlaey":"لكن الذين اتقوا ربهم لهم جنات تجري من تحتها الأنهار خالدين فيها نـزلا من عند الله وما عند الله خير للأبرار","aya_tafseer":"[198] لكن الذين خافوا ربهم، وامتثلوا أوامره، واجتنبوا نواهيه، قد أعدَّ الله لهم جنات تجري من تحت قصورها وأشجارها الأنهار، هي منزلهم الدائم لا يخرجون منه. وما عند الله أعظم وأفضل لأهل الطاعة مما يتقلب فيه الذين كفروا من نعيم الدنيا."},{"id":"492","jozz":"4","page":"76","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"10","line_end":"14","aya_no":"199","aya_text":"وَإِنَّ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ لَمَن يُؤۡمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡكُمۡ وَمَآ أُنزِلَ إِلَيۡهِمۡ خَٰشِعِينَ لِلَّهِ لَا يَشۡتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنٗا قَلِيلًاۚ أُوْلَٰٓئِكَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡۗ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ","aya_text_emlaey":"وإن من أهل الكتاب لمن يؤمن بالله وما أنـزل إليكم وما أنـزل إليهم خاشعين لله لا يشترون بآيات الله ثمنا قليلا أولئك لهم أجرهم عند ربهم إن الله سريع الحساب","aya_tafseer":"[199] وإن بعضاً من أهل الكتاب لَيصدِّق بالله ربّاً واحداً وإلهاً معبوداً، وبما أُنزِل إليكم من هذا القرآن، وبما أُنزِل إليهم من التوراة والإنجيل متذللين لله، خاضعين له، لا يشترون بآيات الله ثمناً قليلاً من حطام الدنيا، ولا يكتمون ما أنزل الله، ولا يحرفونه كغيرهم من أهل الكتاب. أولئك لهم ثواب عظيم عند ربِّهم يوم يلقونه، فيوفيهم إياه غير منقوص. إنَّ الله سريع الحساب، لا يعجزه إحصاء أعمالهم، ومحاسبتهم عليها."},{"id":"493","jozz":"4","page":"76","sura_no":"3","sura_name_en":"Āl-‘Imrān","sura_name_ar":"آل عِمران ","line_start":"14","line_end":"15","aya_no":"200","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱصۡبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ","aya_text_emlaey":"ياأيها الذين آمنوا اصبروا وصابروا ورابطوا واتقوا الله لعلكم تفلحون","aya_tafseer":"[200] يا أيها الذين صَدَّقوا الله ورسوله وعملوا بشرعه اصبروا على طاعة ربكم، وعلى ما ينزل بكم من ضر وبلاء، وغالبوا أعداءكم في الصبر حتى لا يكونوا أشد صبراً منكم، وأقيموا على جهاد عدوي وعدوكم، وخافوا الله في جميع أحوالكم؛ رجاء أن تفوزوا برضاه في الدنيا والآخرة."}]
